(function () {
  const domains = [{"id": "d1", "n": 1, "title": "Prompting and Task Execution", "short": "Prompting", "weight": 14, "blurb": "Write prompts that carry context, role, format, and constraints; decompose big requests into steps; iterate instead of settling; and match the prompting style to analysis, research, drafting, or brainstorming."}, {"id": "d2", "n": 2, "title": "Output Evaluation and Validation", "short": "Evaluation", "weight": 21, "blurb": "The heaviest domain: judge accuracy and completeness, spot hallucinations and bias, verify claims against authoritative sources, know when a human must review, adapt outputs for the audience, and pick the right output format."}, {"id": "d3", "n": 3, "title": "Product and Model Selection", "short": "Products & Models", "weight": 12, "blurb": "Chat vs Projects vs research mode vs artifacts; Haiku vs Sonnet vs Opus; balancing cost, speed, and quality; and managing context windows — when to restart, summarize, or persist."}, {"id": "d4", "n": 4, "title": "Workflow Integration and Solution Design", "short": "Workflows", "weight": 16, "blurb": "Use Claude to analyze requirements, research and plan, design and iterate on solutions, weave AI into existing processes, and explain its value and limits to stakeholders."}, {"id": "d5", "n": 5, "title": "Configuration and Knowledge Management", "short": "Projects & Knowledge", "weight": 12, "blurb": "Configure Claude Projects with instructions and knowledge sources, manage uploads and connectors like Google Drive and Gmail, write system-level instructions, and keep all of it current."}, {"id": "d6", "n": 6, "title": "Governance, Risk, and Responsible Use", "short": "Governance", "weight": 15, "blurb": "Which use cases are appropriate, how to handle sensitive and regulated data, following organizational AI policy, and the ethics of using AI at work."}, {"id": "d7", "n": 7, "title": "Troubleshooting and Optimization", "short": "Troubleshooting", "weight": 10, "blurb": "Diagnose why a prompt underperforms, fix the actual cause, adjust based on feedback, and streamline workflows so they stay fast, cheap, and reliable."}];
  const themes = [{"id": "t1", "title": "Trust, but verify", "body": "Claude's output is a strong first draft, never a finished fact. Anything that leaves your desk — numbers, citations, legal or compliance claims — gets checked against an authoritative source first. Self-reported confidence is not a signal."}, {"id": "t2", "title": "Match the tool to the task", "body": "Model and feature choice is a cost/speed/quality trade-off: fast, cheap models for high-volume routine work; the most capable models for deep reasoning. Same for features — chat for one-offs, Projects for recurring context, research mode for sourced answers, artifacts for shareable deliverables."}, {"id": "t3", "title": "Know when to escalate", "body": "Associates deliver business workflows — and recognize the boundary. Regulated data follows policy, high-stakes outputs get human review, and API builds, integrations, and agentic systems go to Claude Architects and Developers."}];

  const tasks = [
    {"id": "1.1", "d": "d1", "title": "Create effective prompts for business and technical tasks", "concept": "An effective prompt gives Claude the same things you'd give a capable new colleague: context (what's going on), a role or audience, the concrete task, constraints (length, tone, what to include or avoid), and the output format you want. Vague in, generic out.", "antipattern": "One-line prompts that hide the real requirements in your head — 'summarize this report' — then blaming the model when the summary is the wrong length, tone, or focus for the meeting it was for.", "right": "State context, role, task, constraints, and format explicitly. 'Summarize this Q3 ops report in 5 bullets for the executive team; focus on risks and budget variance; plain language, no jargon.'", "tip": "On the exam, the best-prompt option is the one that adds specific context, audience, constraints, and format — not the longest option, and never the one that just says 'be more detailed'.", "analogy": "Briefing a freelancer. 'Write something about our product' gets you a shrug and a generic draft. A one-paragraph brief — audience, goal, tone, length, deadline — gets you work you can actually use.", "pitfall": "Thinking longer prompts are automatically better. Extra words aren't the goal — missing *requirements* are the problem. A tight prompt with the five elements beats a rambling one.", "chat": [{"who": "note", "text": "An operations manager needs a summary of a 30-page vendor report."}, {"who": "user", "label": "Weak prompt", "text": "Summarize this vendor report."}, {"who": "claude", "text": "Here's a summary of the vendor report:\n\nThe report covers the vendor's quarterly performance across delivery, quality, and cost dimensions. Overall performance was mixed, with strong on-time delivery offset by…\n\n(continues for ~600 generic words)"}, {"who": "note", "text": "Accurate but useless for its real purpose — a 5-minute leadership briefing. The requirements were never stated."}, {"who": "user", "label": "Improved prompt", "text": "You're helping me brief our COO. Summarize the attached vendor report in 5 bullets, max 20 words each. Focus on: contract risks, missed SLAs, and anything affecting the Q4 renewal decision. Plain language — no procurement jargon. End with a one-line recommendation."}, {"who": "claude", "text": "• Vendor missed the 99.5% uptime SLA twice (July, September); credits not yet claimed — ~$18K recoverable.\n• Support response times degraded 40% quarter-over-quarter; root cause unresolved.\n• Contract auto-renews Nov 30 unless notice is given by Oct 31.\n• Pricing is 12% above the benchmark quote received in August.\n• Data-handling addendum still unsigned — a compliance gap flagged in June.\n\nRecommendation: issue the non-renewal notice by Oct 31 to preserve leverage, then renegotiate pricing and the addendum."}, {"who": "note", "text": "Context + audience + task + constraints + format = an output ready for the meeting."}], "q": ["p1"], "links": ["1.3", "7.1"]},
    {"id": "1.2", "d": "d1", "title": "Apply task decomposition techniques to structure complex requests", "concept": "Big deliverables fail as single prompts. Decompose them into an explicit sequence of steps — gather, analyze, draft, refine — and run them one at a time, reviewing between steps. Each step's output becomes the next step's input.", "antipattern": "One mega-prompt: 'Analyze our churn data, identify causes, propose fixes, and write the board deck.' Claude produces something for each part, but shallow everywhere, and one early misunderstanding poisons everything after it.", "right": "Break it down and checkpoint: (1) 'List the top churn drivers in this data.' Review. (2) 'For the top 3, propose remediations with effort estimates.' Review. (3) 'Draft board slides from the agreed table.' Each step is small enough to verify.", "tip": "Exam answers that decompose AND insert a human review between steps beat both 'one detailed mega-prompt' and 'fully automate the chain'.", "analogy": "You don't ask a contractor to 'build the house' in one sentence. You sequence it — foundation, framing, wiring — and inspect between phases, catching problems while they're still cheap to fix.", "pitfall": "Decomposing but never reviewing between steps — chaining prompts blindly is the mega-prompt with extra steps. The checkpoint IS the point.", "chat": [{"who": "note", "text": "A project manager needs a full project kickoff pack: risks, timeline, and comms plan."}, {"who": "user", "label": "Weak prompt", "text": "Create the complete kickoff pack for our warehouse migration project: risk register, timeline, stakeholder map, and comms plan."}, {"who": "claude", "text": "Here's a complete kickoff pack:\n\n1. Risk register: (8 generic risks — 'scope creep', 'resource constraints'…)\n2. Timeline: a template Gantt with invented dates\n3. Stakeholder map: placeholder roles\n4. Comms plan: weekly status email…\n\n(plausible-looking, but none of it reflects the actual project)"}, {"who": "note", "text": "Restart, decomposed — step 1 of 3:"}, {"who": "user", "label": "Improved prompt", "text": "Step 1 of 3. Here's our project brief and the constraints [pasted]. List the 8 most significant risks specific to THIS migration, each with likelihood, impact, and owner-role. Nothing generic — every risk must trace to something in the brief."}, {"who": "claude", "text": "Based on your brief:\n\n1. Forklift certification lapse — 4 of 9 operators expire mid-migration (High/High, Ops lead)\n2. WMS cutover conflicts with Black Friday freeze window stated in §2 (Med/High, IT PM)\n3. The 3PL contract requires 90-day notice; brief shows 60 days remaining (High/Med, Procurement)\n…"}, {"who": "user", "text": "Good — risks 1 and 3 are the real ones. Step 2: build a 12-week timeline that resolves those two risks first. I'll review before we draft the comms plan."}, {"who": "note", "text": "Each step is grounded in reviewed output, so errors can't cascade into the final pack."}], "q": ["p2"], "links": ["1.1", "4.2"]},
    {"id": "1.3", "d": "d1", "title": "Iterate prompts to improve output quality", "concept": "First outputs are drafts. Iterating means giving specific, directional feedback — what to keep, what to change, what was wrong — rather than accepting mediocre output or starting over from scratch each time.", "antipattern": "Re-running the same prompt hoping for luck, or feedback with no direction — 'make it better', 'try again' — which changes everything, including the parts that were already right.", "right": "Anchor what's good, target what isn't: 'Keep the structure and the opening. Replace the generic benefits in section 2 with the three metrics I gave you, and cut the length by half.'", "tip": "The exam rewards specific, directional feedback ('shorter, keep X, fix Y with this data') over regenerate-and-hope, and over abandoning the tool after one bad draft.", "analogy": "Editing with a writer, not a vending machine. You don't re-insert coins hoping for a better snack — you mark up the draft: 'tighter intro, cut the third section, more data in the middle'.", "pitfall": "Endless iteration on a prompt that's missing information Claude can't invent. If two rounds of feedback don't converge, the gap is usually missing context — add inputs, don't just re-phrase.", "chat": [{"who": "note", "text": "A comms specialist is drafting an all-hands announcement about a new expense policy."}, {"who": "user", "text": "Draft a short announcement: new expense policy starts March 1 — receipts required for everything over $25, approvals move from managers to Finance, reimbursements now weekly."}, {"who": "claude", "text": "Subject: Important Update to Our Expense Policy\n\nTeam,\n\nWe're excited to announce improvements to our expense process, effective March 1! These changes will streamline operations and improve compliance…\n\n(3 more paragraphs of corporate enthusiasm)"}, {"who": "user", "label": "Vague feedback", "text": "Make it better."}, {"who": "claude", "text": "Subject: Exciting Changes Coming to Expenses!\n\n(a different draft — new tone, new structure, but the same core problems, and the parts that worked are gone too)"}, {"who": "note", "text": "Undirected feedback is a coin re-insert. Try again with anchored, specific feedback:"}, {"who": "user", "label": "Improved feedback", "text": "Keep the subject line and the three policy points. Cut the length by half and drop the 'excited to announce' tone — people dislike this change, so acknowledge it adds a step and explain why (audit findings). End with a link placeholder for the FAQ."}, {"who": "claude", "text": "Subject: Important Update to Our Expense Policy\n\nTeam,\n\nStarting March 1, three things change about expenses: receipts are required for anything over $25, approvals move to Finance, and reimbursements run weekly.\n\nWe know the receipt rule adds a step. It comes directly from last quarter's audit findings, and it protects everyone at reimbursement time.\n\nQuestions? See the FAQ: [link]"}], "q": ["p3"], "links": ["1.1", "7.2"]},
    {"id": "1.4", "d": "d1", "title": "Adapt prompting strategies based on task type", "concept": "Analysis, research, drafting, and brainstorming each want a different prompt shape. Analysis wants criteria and structure; research wants scope and sourcing requirements; drafting wants audience, tone, and format; brainstorming wants quantity, wide constraints, and explicitly deferred judgment.", "antipattern": "One habitual prompt shape for everything — asking for '10 creative options' on a compliance analysis, or demanding a single polished answer during ideation, which kills the variety brainstorming exists to produce.", "right": "Name the mode and shape the prompt for it. Brainstorm: 'Give me 15 raw ideas, no filtering, include unconventional ones.' Analysis: 'Score each vendor against these 5 criteria in a table, cite the row in the data for each score.'", "tip": "Exam stems often hide the task type in a verb: 'explore options' → brainstorming breadth; 'assess/score' → analysis with criteria; 'find out' → research with sources; 'prepare a message' → drafting with audience and tone.", "analogy": "A workshop's stations: measuring, cutting, sanding, painting. Same wood, different technique at each station — sanding with the paint sprayer ends badly.", "pitfall": "Mixing modes in one prompt — 'brainstorm ideas and pick the best one and write the plan' — collapses divergent and convergent thinking into neither.", "chat": [{"who": "note", "text": "An HR lead wants ideas for improving onboarding — a brainstorming task prompted like an analysis task."}, {"who": "user", "label": "Wrong mode", "text": "What is the best way to improve our onboarding process?"}, {"who": "claude", "text": "The most effective single improvement is typically a structured 30-60-90 day plan, because it addresses the most common failure point: unclear expectations. Here's how to implement one…\n\n(one 'best' answer, prematurely converged)"}, {"who": "note", "text": "Asking for 'the best' collapses ideation into one safe answer. Re-prompt in brainstorm mode:"}, {"who": "user", "label": "Improved prompt", "text": "Brainstorm mode: give me 15 distinct ways to improve onboarding for remote engineers. No filtering, no ranking — include cheap quick wins AND unconventional ideas. One line each. We'll evaluate afterwards."}, {"who": "claude", "text": "1. Buddy assigned before day 1, with a budgeted lunch stipend\n2. 'First PR in week 1' — a curated trivial ticket per new hire\n3. Manager sends a 90-second welcome video before start date\n4. Auto-generated 'who to ask about what' map from the org chart\n5. Reverse onboarding: new hire presents fresh-eyes friction report at day 30\n…\n15. 'Documentation bounty' — new hires get rewards for fixing stale docs they hit"}, {"who": "user", "text": "Now switch to analysis mode: score ideas 2, 5, and 15 on cost, time-to-impact, and effect on ramp time, in a table, and note what data we'd need to validate each."}, {"who": "claude", "text": "| Idea | Cost | Time-to-impact | Ramp effect | Validation data needed |\n|---|---|---|---|---|\n| First PR in week 1 | Low | Immediate | High — activates learning by doing | Time-to-first-commit history |\n| Reverse onboarding | Low | 30 days | Medium — improves process, not the individual | Friction themes vs. later attrition |\n| Doc bounty | Med | 2–4 weeks | Medium-high | Doc staleness audit, support-question volume |"}, {"who": "note", "text": "Divergent first, convergent second — two prompts, two shapes, one good decision."}], "q": ["p4"], "links": ["1.1", "4.2"]},
    {"id": "2.1", "d": "d2", "title": "Evaluate Claude-generated outputs for accuracy and completeness", "concept": "Evaluation is a two-question habit applied to every output: Is what's here correct? And is anything missing? Check claims against the source material, and check coverage against the original request — fluent, confident text earns no exemption.", "antipattern": "Skimming for tone and shipping it because it 'reads well'. Fluency bias is the trap: the more confident the prose, the less people check it.", "right": "Evaluate against ground truth, not against vibes: verify every number, name, and date against the source; then re-read the original request and confirm each part was actually addressed — including what the output silently skipped.", "tip": "Exam answers that verify against the source document or original request beat answers that rely on Claude's confidence, formatting quality, or a second AI opinion alone.", "analogy": "Proofreading a new analyst's first report. You don't just read it — you check the numbers against the spreadsheet and the sections against the assignment. Polish is not accuracy.", "pitfall": "Only checking what's present. Omissions are invisible unless you diff the output against the request — the costliest errors are often the missing ones.", "chat": [{"who": "note", "text": "A financial analyst asked Claude to summarize quarterly results from an uploaded spreadsheet."}, {"who": "user", "text": "Summarize the Q3 results from the attached data for our team update."}, {"who": "claude", "text": "Q3 Summary:\n\nRevenue grew 14% quarter-over-quarter to $4.2M, led by the enterprise segment. Churn improved to 2.1%. Headcount costs rose 8%, and gross margin held at 71%. Overall, a strong quarter with all key metrics trending positively."}, {"who": "user", "label": "Evaluation pass", "text": "Before I use this: list every figure in your summary with the exact cell/row in the spreadsheet it came from. Then tell me what from my request — 'results' — your summary did NOT cover."}, {"who": "claude", "text": "Source check:\n• $4.2M revenue — Sheet 'P&L', row 12 ✓\n• 14% QoQ growth — computed from rows 11–12 ✓\n• 2.1% churn — Sheet 'Retention', row 8 ✓\n• 71% gross margin — ⚠ row 15 shows 68.7%; 71% was Q2. This is an error.\n\nNot covered: the spreadsheet also contains the cash-flow tab (Q3 burn increased 22%) and two customer concentration warnings in the notes column — omitted from my summary.\n\nCorrected summary: …"}, {"who": "note", "text": "One accuracy error and two material omissions — caught in 60 seconds because the check targeted sources and coverage, not style."}], "q": ["p5"], "links": ["2.2", "2.3"]},
    {"id": "2.2", "d": "d2", "title": "Identify hallucinations, inconsistencies, and biases in responses", "concept": "Hallucinations are fabricated specifics — citations, statistics, quotes, features — delivered with the same fluent confidence as real facts. Inconsistencies are internal contradictions between parts of one output. Bias is systematic skew — in framing, examples, or assumptions. All three are detected by inspection, never by asking the model how confident it is.", "antipattern": "Treating specificity as credibility. 'Section 4.2.1 of the regulation' and 'a 2024 Gartner study found 73%' FEEL verified precisely because they're specific — that's what makes hallucinated details dangerous.", "right": "Red-flag the checkable specifics (citations, numbers, quotes, section references), verify them externally, scan long outputs for internal contradictions, and ask 'whose perspective is missing?' for bias.", "tip": "Any exam option that verifies against an authoritative external source beats any option involving self-reported confidence, rewording, or 'it sounded specific'.", "analogy": "A witness who never says 'I don't remember' — every gap in memory gets filled with a plausible invention, told in the same steady voice as the truth. You cross-examine the details, not the delivery.", "pitfall": "Asking Claude to rate its own confidence and treating a high rating as verification. Self-assessment is not a reliability signal — the official sample question tests exactly this.", "chat": [{"who": "note", "text": "A paralegal asked Claude about a data-retention regulation. (This mirrors official sample question 1.)"}, {"who": "user", "text": "What does the GDPR say about how long we can keep customer support recordings?"}, {"who": "claude", "text": "Under GDPR Article 5(1)(e) — the storage limitation principle — personal data may be kept only as long as necessary for the stated purpose. For support recordings, supervisory authorities have commonly endorsed a 6-month retention ceiling, as reflected in the EDPB's 2021 guidance §4.3, which names call recordings specifically."}, {"who": "user", "label": "Verification pass", "text": "Which parts of that answer are you able to state from the regulation's actual text, and which parts should I independently verify before citing them to our DPO?"}, {"who": "claude", "text": "Verify before citing:\n• The '6-month ceiling' — I cannot point to a binding source; retention periods are purpose-based, not fixed. Treat this as unverified.\n• 'EDPB 2021 guidance §4.3 names call recordings' — I may be conflating documents; the section number could be wrong or fabricated. Check the EDPB's actual publications.\n\nSolid: Article 5(1)(e) storage limitation exists and applies; the purpose-based principle is correct.\n\nThe safe path: confirm the specific guidance and any numeric period against the official EDPB text before this reaches your DPO."}, {"who": "note", "text": "The plausible §-references were the hallucination risk. Specific ≠ verified — check specifics against the official source."}], "q": ["p6"], "links": ["2.3", "2.1"]},
    {"id": "2.3", "d": "d2", "title": "Apply fact-checking and validation techniques", "concept": "Validation is a toolkit, matched to the claim: check citations against the official document, recompute numbers from raw data, cross-check independent sources for factual claims, and route domain judgments to a human expert. The effort should scale with the stakes of being wrong.", "antipattern": "Validating by asking the same model 'are you sure?' — it will often double-down fluently — or fact-checking a compliance summary by rewording it until it sounds more formal.", "right": "Match the technique to the claim type: citation → open the cited source; statistic → recompute or trace to the original dataset; legal/regulated claim → authoritative text plus expert review; general fact → two independent sources.", "tip": "Official sample question 1 is this lesson: a confident regulatory summary citing a specific subsection must be verified against the official regulation text before it goes to compliance. Not confidence ratings, not rewording.", "analogy": "Airport security has different lanes — metal detector for everyone, extra screening for flagged items. Every output passes a quick scan; high-stakes claims get the full pat-down.", "pitfall": "Uniform effort — deep-verifying trivia while waving high-stakes claims through because 'there's no time'. Stakes decide depth, not convenience.", "chat": [{"who": "note", "text": "An associate prepared a market-size estimate with Claude and now validates it before the investment memo."}, {"who": "user", "text": "Your draft says: 'The EU cold-chain logistics market was €9.8B in 2024 (Statista), growing 12% annually, and new F-Gas rules (Regulation 2024/573, Art. 12) will retire 30% of refrigerated fleets by 2027.' Give me a validation plan for each claim before this goes in the memo."}, {"who": "claude", "text": "Claim-by-claim validation plan:\n\n1. '€9.8B (Statista)' — a checkable citation. Open the actual Statista page; confirm figure, year, and market definition match. Risk: I may have blended adjacent market reports.\n\n2. '12% annual growth' — a statistic. Trace to a named report and check the period it covers; if it's my synthesis, recompute from primary figures.\n\n3. 'Regulation 2024/573, Art. 12 retires 30% of fleets' — highest stakes. The regulation number is real, but verify Article 12's actual text on EUR-Lex; the '30% by 2027' reads like an industry-analysis projection, not regulatory text. Separate what the LAW says from what analysts predict, and have your compliance contact confirm the interpretation.\n\nStakes ranking: claim 3 (memo's core argument) > claim 1 > claim 2."}, {"who": "user", "text": "Checked: Statista says €9.1B not €9.8B, and Art. 12 covers labeling — the fleet phase-out is in Annex IV. Update the draft with correct sourcing."}, {"who": "claude", "text": "Updated: '…was €9.1B in 2024 (Statista, EU cold-chain logistics, retrieved Jul 2026)… the F-Gas Regulation (EU) 2024/573 — Annex IV phase-down schedule — is projected by industry analysts to force replacement of a substantial share of refrigerated fleets by 2027 (projection, not regulatory mandate).'\n\nBoth errors would have survived a confidence check — they only fell to source verification."}], "q": ["q1"], "links": ["2.2", "2.4"]},
    {"id": "2.4", "d": "d2", "title": "Determine when human review or additional verification is required", "concept": "Some outputs must pass through a qualified human regardless of how good they look: legal, medical, financial, and HR/personnel content; anything public or contractual; irreversible decisions; and regulated communications. The trigger is the category and its consequences, not the output's apparent quality.", "antipattern": "Quality-gating by impression: 'it looked right, so I sent it.' Or the opposite failure — routing everything to review, which buries reviewers and trains them to rubber-stamp.", "right": "Define review triggers by category and consequence up front: external + binding + regulated + irreversible → expert review, always. Routine internal drafts → self-review. Calibrate so reviewers see the few items that matter.", "tip": "When an exam scenario mentions compliance, contracts, medical/legal content, or an external audience, the correct option almost always includes a qualified human checkpoint before use — and the wrong options ship it because it 'looked accurate'.", "analogy": "A pharmacist checks every prescription — not because doctors are usually wrong, but because the cost of the rare error is unacceptable. The check is triggered by the category 'prescription', not by suspicion.", "pitfall": "Assuming iteration substitutes for review — ten rounds of refinement with Claude is still zero qualified human eyes on a contract clause.", "chat": [{"who": "note", "text": "A sales ops associate drafted contract-renewal language with Claude."}, {"who": "user", "label": "Risky shortcut", "text": "This renewal clause you drafted looks perfect. I'll paste it into the customer's contract — Legal is backed up for a week and the deal closes tomorrow."}, {"who": "claude", "text": "Before you do — this crosses several mandatory-review triggers at once: it's contractual (binding), external (customer-facing), and it modifies liability language (consequences are irreversible once signed).\n\nMy draft is a starting point written without access to your master services agreement, the customer's negotiated terms, or your jurisdiction's requirements. A clause that 'looks perfect' can still conflict with the MSA's precedence rules or waive protections you rely on.\n\nOptions that keep the deal moving:\n• Send Legal the single clause (not the whole contract) flagged 'one-clause review, closing tomorrow'\n• Use the pre-approved fallback language from your clause library if one exists\n• Close on the current term with a documented amendment window\n\nWhat I can safely do now: produce a redline comparison against your standard template so Legal's review takes minutes instead of hours."}, {"who": "user", "text": "Fair. Generate the redline against our standard renewal template and a 3-line summary of what changed for Legal."}, {"who": "claude", "text": "Redline attached. Summary for Legal:\n1. Renewal term extended 12 → 24 months (customer request)\n2. Price escalator capped at 4% (was uncapped) — revenue impact\n3. ⚠ Liability cap wording changed from 'fees paid in prior 12 months' to 'fees paid' — this one needs your judgment.\n\nItem 3 is exactly why this category gets human review."}], "q": ["p7"], "links": ["2.3", "6.3"]},
    {"id": "2.5", "d": "d2", "title": "Edit, adapt, refine, and compare outputs for the intended audience", "concept": "One set of facts, many audiences. Adapting means changing depth, vocabulary, framing, and emphasis for who's reading — executives want decisions and impact, engineers want specifics, customers want clarity and reassurance. Generating variants and comparing them is faster than perfecting one.", "antipattern": "Writing once for everyone — the all-purpose memo that's too technical for execs and too vague for practitioners — or 'dumbing down' by deleting content instead of translating it.", "right": "Name the audience and what they need to DO with the information, generate purpose-built variants, and compare side-by-side: 'Rewrite this incident report as (a) a 3-line exec summary focused on customer impact, (b) a customer notice — plain, honest, no internal jargon.'", "tip": "Exam options that specify the audience and adapt framing/depth for it beat options that shorten, formalize, or 'polish' without an audience in mind.", "analogy": "A doctor explaining one diagnosis three ways: to the patient (plain language, what happens next), to a colleague (terminology, differentials), to the insurer (codes and criteria). Same truth, three renderings.", "pitfall": "Adaptation that drifts from the facts — simplifying a caveat until it's no longer true. Every variant must stay faithful to the source; simpler words, same claims.", "chat": [{"who": "note", "text": "An IT manager has a technical incident postmortem and three audiences to inform."}, {"who": "user", "text": "Here's the postmortem [pasted]: a misconfigured load balancer caused 43 minutes of checkout failures, ~$31K in abandoned carts, fixed by rolling back config change #4471. I need three versions: exec summary, customer status-page notice, and a note for the engineering wiki."}, {"who": "claude", "text": "1) EXEC SUMMARY (decisions + impact):\n'Checkout was down 43 min on Tue (~$31K est. lost sales). Cause: a config change that skipped review. Fixed same day. We're adding a mandatory review gate for load-balancer changes — no budget ask; process change only.'\n\n2) CUSTOMER STATUS PAGE (clarity + reassurance, no jargon):\n'On Tuesday between 14:02–14:45 UTC, some customers couldn't complete purchases. This was caused by an internal configuration error — no customer data was affected. The issue is fully resolved, and we've added safeguards to prevent recurrence. We're sorry for the disruption.'\n\n3) ENGINEERING WIKI (specifics, reproducibility):\n'Change #4471 modified the LB health-check path without updating the target group, draining all healthy checkout pods… Rollback via `deploy revert 4471`. Action items: health-check config now requires 2-reviewer approval; alert added on >50% target drain.'"}, {"who": "user", "text": "In the customer notice, 'no customer data was affected' — is that supported by the postmortem, or did adaptation add a claim?"}, {"who": "claude", "text": "Good catch — the postmortem doesn't address data at all; I added reassurance that isn't sourced. Either verify that claim with the security team before publishing, or drop it:\n\n'…caused by an internal configuration error. The issue is fully resolved…'\n\nAdaptation may change framing and depth, but it must never add claims the source doesn't support."}], "q": ["p8"], "links": ["1.1", "2.6"]},
    {"id": "2.6", "d": "d2", "title": "Organize and curate information and select appropriate output formats", "concept": "Choosing the output format is part of the work: inline chat for quick back-and-forth, artifacts for documents/tables/code you'll refine, share, or reuse, and structured data (tables, CSV, JSON) when the output feeds another tool or needs comparison. Curation — ordering, grouping, cutting — is what turns information into something usable.", "antipattern": "Everything as one long chat reply — a 40-row comparison buried in prose paragraphs, a policy document scrolled past in chat instead of maintained as an artifact, data re-typed by hand because it wasn't structured.", "right": "Ask for the format the next step needs: 'as a sortable table with these 6 columns', 'as an artifact I can iterate on and share', 'as CSV I can paste into Sheets'. Group, rank, and cut to what the reader will actually use.", "tip": "Exam cue: 'will be updated/shared/reused' → artifact; 'imported/analyzed elsewhere' → structured data (CSV/JSON/table); 'quick answer in conversation' → inline. Pick by downstream use, not by looks.", "analogy": "The difference between handing someone a shoebox of receipts and a categorized expense report. Same information; only one is usable. Format and organization are the deliverable, not decoration.", "pitfall": "Over-formatting trivial answers (a table for two facts) and under-formatting dense ones. The format serves retrieval and reuse — match it to how the output will be consumed.", "chat": [{"who": "note", "text": "A procurement analyst is comparing SaaS vendors and will import the result into a tracking sheet."}, {"who": "user", "label": "Weak prompt", "text": "Compare the three CRM vendors from the docs I uploaded."}, {"who": "claude", "text": "Vendor A offers strong pipeline management and integrates with your email stack, priced at $45/user/month. Vendor B, at $38/user/month, emphasizes automation but has weaker reporting. Vendor C…\n\n(four paragraphs of prose — informative, impossible to compare or import)"}, {"who": "user", "label": "Improved prompt", "text": "Redo as a comparison table: rows = the 7 criteria from our RFP doc, columns = the 3 vendors, cells max 8 words, with a ✓/✗/partial verdict per cell. Then give me the same thing as CSV so I can paste it into our tracking sheet. Order criteria by weight from the RFP."}, {"who": "claude", "text": "| Criterion (RFP weight) | Vendor A | Vendor B | Vendor C |\n|---|---|---|---|\n| SSO/SAML (25%) | ✓ included | ✓ +$6/user | ✗ roadmap only |\n| API limits (20%) | ✓ 100K/day | partial 10K/day | ✓ unlimited |\n| Email integration (15%) | ✓ native | ✓ native | partial via Zapier |\n…\n\nCSV:\ncriterion,weight,vendor_a,vendor_b,vendor_c\nsso_saml,25%,included,paid_addon,roadmap\napi_limits,20%,100k_day,10k_day,unlimited\n…"}, {"who": "user", "text": "Also make the full comparison an artifact — I'll be updating it as demo calls happen and sharing it with the committee."}, {"who": "note", "text": "Reused + shared + updated → artifact. Imported → CSV. Quick question → inline. The downstream use picks the format."}], "q": ["p9"], "links": ["2.5", "3.1"]},
    {"id": "3.1", "d": "d3", "title": "Select appropriate Claude product features (Projects, research mode, chat, artifacts)", "concept": "Each feature answers a different need: plain chat for one-off tasks; Projects when the same context (instructions + documents) recurs across many chats; research mode when the answer must come from current, cited web sources; artifacts when the deliverable is a document, table, page, or code you will refine, share, or reuse.", "antipattern": "Re-pasting the same brand guide and product sheet into every new chat — or asking plain chat for 'the latest' market figures, which its training data cannot reliably contain.", "right": "Recurring context → set up a Project once. Current sourced facts → research mode, then verify citations. Shareable deliverable → artifact. Quick one-off → chat. Combine them: a Project chat can still use research mode and produce artifacts.", "tip": "Exam cue-words: 'every week / the whole team / same documents' → Projects; 'current / latest / with sources' → research mode; 'share / iterate on a document' → artifact; 'quick question' → chat.", "analogy": "Kitchen stations: the cutting board for quick prep (chat), the labeled pantry you restock once and cook from daily (Projects), sending a runner to the market for today's prices (research mode), and the plated dish that leaves the kitchen (artifacts).", "pitfall": "Thinking features are exclusive tiers. They compose — the question is what the task needs: persistent context, live sources, a durable deliverable, or none of the above.", "chat": [{"who": "note", "text": "A marketing associate produces a weekly competitor newsletter and keeps starting from scratch."}, {"who": "user", "label": "Weak setup", "text": "(new chat, again) You're a market analyst. Our positioning: [pastes 2 pages]. Our competitors: [pastes list]. Our tone guide: [pastes]. Now write this week's competitor update."}, {"who": "claude", "text": "Here's this week's competitor update based on the positioning and tone you've provided…\n\n(a decent draft — but this same 10-minute setup happens every single week, and the analysis can't include anything newer than my training data)"}, {"who": "note", "text": "Two mismatches: recurring context re-pasted weekly, and 'this week's news' requested without live sources."}, {"who": "user", "label": "Improved setup", "text": "I've created a 'Competitor Newsletter' Project with our positioning doc, competitor list, and tone guide as Project knowledge, plus instructions for the newsletter format. In this Project chat: use research mode to find this week's announcements from our top 3 competitors, then draft the newsletter as an artifact."}, {"who": "claude", "text": "Using your Project's positioning and tone guide.\n\nResearch (sources cited): Competitor A announced a Salesforce integration Tuesday [1]; Competitor B raised prices 8% on the mid tier [2]; Competitor C published a healthcare case study [3].\n\nDraft newsletter created as an artifact — formatted per your Project instructions, positioning each item against our differentiation. Edit or share it from the panel; next week, just open a new chat in this Project and say 'this week's edition'."}, {"who": "note", "text": "Project = persistent context · research mode = current cited facts · artifact = the reusable deliverable."}], "q": ["p10"], "links": ["5.1", "2.6"]},
    {"id": "3.2", "d": "d3", "title": "Differentiate between Claude model types (Haiku, Sonnet, Opus)", "concept": "The model families trade capability against speed and cost. Haiku: fastest and most economical — high-volume, well-defined, straightforward tasks. Sonnet: the balanced default for everyday professional work. Opus: the most capable — deep multi-step reasoning, complex analysis, and the hardest problems, at higher cost and latency.", "antipattern": "'Always use the biggest model to be safe' — paying Opus cost and latency for thousands of routine replies — or its mirror: forcing the cheapest model through a dense legal analysis and trusting whatever comes out.", "right": "Classify the task first: volume + simple + speed-sensitive → Haiku; standard drafting/analysis → Sonnet; genuinely complex reasoning where quality dominates cost → Opus. Re-evaluate when the task changes shape.", "tip": "Official sample question 2 is this lesson verbatim: high-volume short replies where speed and cost matter → the faster, lower-cost model. 'Most capable everywhere' is always the distractor.", "analogy": "Shipping options: courier bike (Haiku — fast, cheap, small parcels), delivery van (Sonnet — the everyday workhorse), freight team with an engineer (Opus — when the cargo is genuinely complex). You don't book the freight team to deliver an envelope.", "pitfall": "Treating model choice as a quality knob only. It's a three-way trade — a 10x-volume task at slightly lower per-item quality is often the better business outcome, and the exam frames it that way.", "chat": [{"who": "note", "text": "A support ops lead is sizing models for two very different jobs."}, {"who": "user", "text": "Two tasks: (1) auto-draft first-reply suggestions for ~2,000 routine support tickets/day — agents review before sending; (2) a quarterly root-cause analysis across 6 months of escalation data for the exec team. Which model for each?"}, {"who": "claude", "text": "Task 1 → Haiku. The work is high-volume, well-defined (classify + template a first reply), latency-sensitive (agents wait on it), and human-reviewed (a safety net exists). Paying Opus prices here multiplies cost ~2,000×/day for quality differences your reviewers would mostly overwrite anyway.\n\nTask 2 → Opus. It's low-volume (once a quarter), genuinely complex (cross-referencing months of data, causal reasoning, exec-facing conclusions), and the cost of a wrong conclusion dwarfs the model cost. Speed is irrelevant.\n\nIn between — say, drafting the monthly ops report — Sonnet is the default: strong quality at everyday cost."}, {"who": "user", "text": "Our CFO asked: why not just use the best model for everything, so quality is never a question?"}, {"who": "claude", "text": "Because 'best' is per-task, not absolute. For task 1, Opus buys marginal quality your review step already provides — while adding real cost (×2,000/day) and latency agents feel on every ticket. Quality, efficiency, and cost are a three-way balance: reserve the most capable model for work that needs its reasoning, and the routine work funds itself. That balancing act — not maximal spend — is what responsible AI usage looks like to an auditor, too."}], "q": ["p11"], "links": ["3.3", "3.1"]},
    {"id": "3.3", "d": "d3", "title": "Align model selection with task requirements (cost, speed, quality)", "concept": "Model selection is requirements engineering: list what the task actually needs — accuracy floor, latency ceiling, volume, budget, review safety nets — then pick the cheapest/fastest model that clears the bar. Quality requirements are set by consequences, not by prestige.", "antipattern": "Choosing the model before stating requirements — by habit, by brand ('always the top model'), or by budget panic ('always the cheapest') — and never revisiting the choice as volume or stakes change.", "right": "Write the requirement sentence first: 'X outputs/day, replies within Y seconds, error tolerance Z because [review step / audience]'. The model that satisfies it at lowest cost wins. When requirements change, re-decide.", "tip": "Exam options that name the trade-off ('faster, lower-cost model suited to high-volume straightforward tasks') beat options that disable features, switch platforms, or maximize capability 'to be safe'.", "analogy": "Hiring for a role: you don't hire the most senior candidate for every opening — you write the job requirements first, then hire the person who meets them. Over-hiring burns budget; under-hiring burns quality.", "pitfall": "Ignoring the review structure around the task. A human-reviewed draft tolerates a faster model; an unreviewed customer-facing answer raises the quality floor — the workflow, not just the task, sets the requirement.", "chat": [{"who": "note", "text": "An operations manager is budgeting an AI-assisted invoice-processing workflow."}, {"who": "user", "label": "Requirements first", "text": "Help me pick a model by requirements, not vibes. The task: extract 5 fields from ~800 supplier invoices/day into our AP system. A clerk spot-checks 10%. Wrong extractions cost ~20 min each to fix. Budget matters; each invoice should process in under 10 seconds."}, {"who": "claude", "text": "Requirements translation:\n• Volume: 800/day → per-unit cost is multiplied ×800×22 workdays — cost sensitivity HIGH\n• Latency: <10s → rules out nothing, but favors faster models\n• Quality floor: 5 well-defined fields from semi-structured documents = a straightforward extraction task; 10% human spot-check exists\n• Error economics: a miss costs 20 min of clerk time — tolerable at low rates, expensive at high rates\n\nRecommendation: start with Haiku. The task is high-volume and well-defined — its profile. Run a 200-invoice pilot, measure field-level accuracy against the clerk's corrections. If accuracy on any field falls below your threshold (say 97%), step that field — or the whole flow — up to Sonnet and re-measure. Opus is not on the table: nothing here needs deep reasoning."}, {"who": "user", "text": "Pilot ran: 98.6% field accuracy, but the 'payment terms' field only hit 91% — suppliers write it in wildly inconsistent formats."}, {"who": "claude", "text": "Textbook split decision: keep Haiku for the four fields that clear the bar, and either (a) route just the payment-terms field to Sonnet, or (b) add two examples of the messy formats to the prompt and re-test Haiku first — cheaper if it works. Requirements set the floor per field, not per project; pay for capability only where the task actually demands it."}], "q": ["q2"], "links": ["3.2", "7.3"]},
    {"id": "3.4", "d": "d3", "title": "Understand and manage context limitations and memory considerations", "concept": "A conversation's context window is finite: very long chats slow down, lose track of early details, and eventually can't fit more. Manage it deliberately — start fresh chats per task, ask for a summary to carry key decisions forward, and persist durable context in Project instructions/knowledge instead of re-explaining it every session.", "antipattern": "One eternal mega-chat for everything — week three, Claude 'forgets' the constraint from day one, responses degrade, and the fix attempted is typing the constraint again into the same overloaded conversation.", "right": "One task, one chat. Before switching or when a chat gets long: 'Summarize the decisions, constraints, and open items so far' → carry that into a fresh chat. Anything needed across ALL chats → Project instructions or knowledge, not chat history.", "tip": "Exam cue: 'long conversation, quality degrading, early instructions ignored' → summarize and restart (or move durable context to a Project) — not 'repeat the instruction louder' and not 'the model is broken'.", "analogy": "A whiteboard in a long meeting: it fills up. You either photograph the decisions and wipe it (summarize + restart), or pin the permanent reference material on the wall next to it (Project knowledge) so the board holds only today's work.", "pitfall": "Confusing chat history with durable memory. A conversation is a workspace, not a filing cabinet — if it must survive the session, persist it in the Project (or your own docs), explicitly.", "chat": [{"who": "note", "text": "A program manager has run one continuous chat for three weeks of vendor negotiation prep."}, {"who": "user", "label": "Degrading mega-chat", "text": "Draft the counter-offer email like we discussed. Remember the walk-away price we set at the start."}, {"who": "claude", "text": "Here's the counter-offer draft…\n\n(the draft cites a $120K ceiling — but the walk-away agreed on day one was $95K; that constraint is buried under three weeks of accumulated conversation and is no longer reliably in view)"}, {"who": "user", "text": "That's wrong — we said $95K weeks ago. Why did you lose it?"}, {"who": "claude", "text": "You're right, and the honest answer is a context limitation: this conversation now contains weeks of material, and early details can fall out of my effective working view. Rather than patching this chat, let's fix the structure:\n\n1. I'll produce a NEGOTIATION BRIEF summarizing everything durable — walk-away $95K, agreed terms, open items, decision log.\n2. Save it to your 'Vendor Negotiation' Project as knowledge (or pin it in instructions).\n3. Start each work session as a fresh chat in that Project — it loads the brief automatically, and the chat stays short and sharp.\n\nWant the brief now?"}, {"who": "user", "label": "Fixed structure", "text": "Yes — generate the brief. I'll add it to the Project and we'll do the counter-offer in a fresh chat."}, {"who": "claude", "text": "NEGOTIATION BRIEF (v1, carries all durable context):\n• Walk-away: $95K max annual — HARD LIMIT set 2026-06-24\n• Must-haves: 24-mo term, quarterly exit clause, EU data residency\n• Conceded: onboarding fee (waived by them 7/02)\n• Open: SLA credits %, renewal cap\n• Next: counter-offer email\n\nFresh chat + this brief = every future draft starts from the facts, not from fading memory."}], "q": ["p12"], "links": ["3.1", "5.1"]},
    {"id": "4.1", "d": "d4", "title": "Apply Claude to analyze requirements and use cases", "concept": "Before building anything, use Claude to interrogate the problem: surface unstated requirements, identify stakeholders and constraints, separate must-haves from nice-to-haves, and pressure-test whether the stated ask is the real need. Claude is a structured thinking partner, not just a producer.", "antipattern": "Jumping straight to production — 'build me the rollout plan' — on an unexamined request, then discovering mid-rollout that the requirement everyone assumed was never actually agreed.", "right": "Make Claude interrogate before it produces: 'Before drafting anything, list the questions this request leaves unanswered, the stakeholders affected, and the constraints implied. Then propose acceptance criteria we can validate with the requester.'", "tip": "Exam scenarios about vague requests reward 'clarify requirements / define success criteria first' over 'produce the deliverable immediately' — analysis before artifact.", "analogy": "A good consultant's first meeting: they don't quote a price for 'a new website' — they ask what the website is supposed to achieve, for whom, by when, within what constraints. The questions ARE the analysis.", "pitfall": "Accepting Claude's inferred requirements as decisions. Its analysis surfaces candidate requirements — a human confirms them with the actual stakeholders before they become commitments.", "chat": [{"who": "note", "text": "A department head forwards a one-line request: 'We need an AI chatbot for HR.'"}, {"who": "user", "label": "Unexamined ask", "text": "Leadership wants an AI chatbot for HR. Draft the project plan."}, {"who": "claude", "text": "I can draft that — but a plan built on a one-line requirement will encode guesses as commitments. Let me analyze the request first:\n\nUnanswered questions:\n• Who is it for — all employees, HR staff, or candidates?\n• What top tasks? (benefits questions ≠ leave requests ≠ policy lookup — very different builds)\n• What may it answer autonomously vs. must it route to a human? (payroll and personal data raise governance flags)\n• Success metric — deflection rate? response time? HR hours saved?\n\nStakeholders: HR ops, IT/security, works council/employee reps (monitoring concerns), legal (PII).\n\nImplied constraints: must respect data privacy for personnel records; probably needs your existing HR knowledge base as its source.\n\nProposed acceptance criteria to validate with leadership:\n1. Answers top-20 benefits/policy questions from the official handbook, with links\n2. Never discusses individual personnel data; routes those to HR staff\n3. Cuts tier-1 HR email volume 30% in 90 days\n\nShall I turn these into a one-page requirements summary for the leadership meeting?"}, {"who": "user", "text": "Yes — and add a half-page of use cases ranked by value vs. effort so they can choose scope."}, {"who": "claude", "text": "Requirements summary + ranked use cases drafted:\n\nHigh value / low effort: benefits FAQ, policy lookup with handbook citations, onboarding checklist guidance\nHigh value / higher effort: leave-request status (needs HRIS integration — escalate to IT)\nOut of scope v1: anything touching individual records (governance review first)\n\nThe leadership decision is now about scope and criteria — not about a guessed plan."}], "q": ["p13"], "links": ["4.3", "1.2"]},
    {"id": "4.2", "d": "d4", "title": "Leverage Claude for research, planning, and process optimization", "concept": "Claude accelerates the thinking work around execution: synthesizing research into decision-ready comparisons, drafting plans with dependencies and risks, and analyzing an existing process to find bottlenecks, redundancies, and automation candidates.", "antipattern": "Using Claude only at the final step (write the doc) while doing the research synthesis and planning manually — or accepting its process recommendations without validating them against how work actually flows.", "right": "Bring Claude the raw material and the decision to be made: 'Here are our 6 process steps with owners and timings [paste]. Identify bottlenecks, handoff risks, and steps that could be parallelized or automated; rank by expected time saved.'", "tip": "The exam rewards using Claude to structure and synthesize (options, trade-offs, dependencies, bottleneck analysis) with humans validating — over both manual-only work and blind delegation.", "analogy": "A chief of staff: gathers the background, drafts the plan of attack, spots where the operation wastes motion — so the decision-maker spends their time deciding, not compiling.", "pitfall": "Research without recency awareness — for anything time-sensitive, pair Claude's synthesis with research mode or your own current sources, and keep citations attached so claims stay checkable.", "chat": [{"who": "note", "text": "An ops lead suspects the employee-onboarding process is bloated."}, {"who": "user", "text": "Here's our onboarding process, step by step with owners and average durations [pasted: 14 steps, 11 business days total]. Where is it slow and what would you change?"}, {"who": "claude", "text": "Analysis of your 14 steps:\n\nBOTTLENECK: Steps 4–6 (IT access requests) account for 5 of the 11 days — three sequential tickets that could be one parallel bundle triggered at contract signature instead of day 1.\n\nREDUNDANCY: Steps 8 and 12 both collect emergency-contact data (HR form, then facilities form) — merge.\n\nHANDOFF RISK: Step 9 (manager schedules intro meetings) has no owner-of-record when the manager is on leave — 3 of your last 10 onboardings stalled here per your durations.\n\nAUTOMATION CANDIDATES (ranked by days saved):\n1. Pre-trigger IT bundle at signature: −4 days\n2. Auto-schedule intro meetings from a template calendar: −1 day\n3. Merge duplicate forms: −0.5 day admin time\n\nProjected: 11 days → ~5.5. Caveat: I'm reasoning from your documented process — validate with the people who run steps 4–6 whether the sequential ordering has a real dependency I can't see (e.g., security policy)."}, {"who": "user", "text": "IT says the sequence exists because badge requests need an employee ID that's only created in step 3. Adjust."}, {"who": "claude", "text": "Adjusted: trigger step 3 (ID creation) at signature — it has no upstream dependency — then the IT bundle fires the same day. Projection holds at ~6 days. This is exactly why the human check matters: the plan is now grounded in the real constraint, not my inference of it."}], "q": ["p14"], "links": ["1.2", "7.3"]},
    {"id": "4.3", "d": "d4", "title": "Use Claude to support solution design, development, and iteration", "concept": "For a business problem, Claude supports the full design arc: generate solution options with trade-offs, help select against criteria, draft the chosen design (process, template, document, rollout), and iterate it against feedback and pilot results — with the associate steering each turn.", "antipattern": "One-shot solutioning: taking Claude's first proposed design straight to rollout — no alternatives compared, no pilot feedback loop — then patching in production what a pilot would have caught.", "right": "Run the arc explicitly: 'Give me 3 approaches with trade-offs' → pick one against named criteria → 'draft the full design' → pilot → 'here's what broke and the feedback [paste]; revise.' Each artifact improves through evidence.", "tip": "Exam answers that generate options → select by criteria → pilot → iterate beat both 'implement Claude's first suggestion org-wide' and 'don't use AI for design work'.", "analogy": "An architect's studio process: sketches first (options), then the client picks a direction (selection), then blueprints (design), then revisions after the walkthrough (iteration). Nobody builds from the first sketch.", "pitfall": "Letting iteration drift from the success criteria set at the start — every revision should be checked against the same yardstick, or you optimize toward whoever complained loudest.", "chat": [{"who": "note", "text": "A customer success manager must fix a broken QBR (quarterly business review) prep process."}, {"who": "user", "text": "Our CSMs spend 6 hours prepping each QBR deck manually. Design me a better process — but options first, not one answer. Criteria: prep time under 2 hours, data accuracy, works for our 40 CSMs without new software."}, {"who": "claude", "text": "Three approaches with trade-offs against your criteria:\n\nA) TEMPLATE + CLAUDE DRAFT: Standard deck template; CSM exports account data, Claude drafts commentary per slide. Prep ~1.5h. Accuracy depends on export discipline. No new software. Risk: garbage-in commentary.\n\nB) CLAUDE PROJECT PER SEGMENT: Projects preloaded with playbooks + template; CSMs drop in the account export, get a full draft. Prep ~1h. Higher consistency. Setup effort up front; knowledge must be maintained.\n\nC) FULL AUTOMATION VIA API: Auto-generated decks from the CRM. Prep ~15min but violates your 'no new software' constraint and needs engineering — out of scope for your team (escalation territory).\n\nAgainst your criteria, B wins on time and consistency; A is the fastest to pilot. Recommend: pilot A with 3 CSMs for two weeks; if commentary quality holds, invest in B's Project setup."}, {"who": "user", "label": "After pilot", "text": "Pilot feedback: prep dropped to 100 min, but two CSMs said the drafts misread declining-usage accounts as healthy because the export omits the usage-trend tab."}, {"who": "claude", "text": "Root cause is input completeness, not the drafting. Revision to the design:\n1. Export checklist now names the usage-trend tab as REQUIRED — the draft prompt refuses to assess health without it\n2. Added a 'health assessment' rubric to the template: usage trend, support tickets, champion status — so commentary is criteria-driven, not inferred\n3. Re-pilot with the same 3 CSMs against the same yardstick: <2h prep AND zero misread health calls\n\nSame criteria, better evidence, third iteration. That's the arc working."}], "q": ["p15"], "links": ["4.1", "1.3"]},
    {"id": "4.4", "d": "d4", "title": "Integrate Claude into existing workflows to augment or redesign them", "concept": "Integration means deciding where AI sits inside a workflow that already exists: augment specific steps (draft, summarize, classify) while humans keep judgment steps, or redesign the flow around what AI makes newly possible. Map the workflow first; insert AI where it removes real friction; keep humans at decision and quality gates.", "antipattern": "Bolting AI onto a process nobody mapped ('use Claude for… everything?'), automating the judgment steps while leaving the drudgery manual, or leaving no human gate before outputs reach customers.", "right": "Map steps → classify each as drudgery (summarize, reformat, first-draft, classify) vs judgment (approve, decide, negotiate) → augment drudgery with Claude, keep judgment human, define the handoff points explicitly, measure before/after.", "tip": "Exam answers that keep humans at judgment/quality gates and insert AI at well-defined drudgery steps beat 'automate end-to-end' and 'ban AI from the workflow' alike.", "analogy": "Adding a power tool to a workshop that already builds furniture. You don't bolt it randomly to a bench — you find the step that's slow (rough cutting), fit the tool there, and keep the craftsman on the finish work.", "pitfall": "Skipping change management. A redesigned workflow fails if the team doesn't know when to trust the AI step, when to override it, and who owns its errors — write that down as part of the design.", "chat": [{"who": "note", "text": "A recruiting lead wants AI in the hiring pipeline 'somewhere useful'."}, {"who": "user", "text": "We want Claude in our recruiting workflow. Current flow: (1) source candidates, (2) screen 200+ CVs/role, (3) phone screens, (4) interview loops, (5) offer decision. Where does it belong — and where does it NOT?"}, {"who": "claude", "text": "Step-by-step classification:\n\n(2) CV screening — AUGMENT, carefully: Claude can extract and structure each CV against the published role requirements (skills, experience, location) into a comparable summary sheet. But per your jurisdiction's rules and good practice, it should structure information for humans — not auto-reject candidates. A recruiter reviews every 'no'. This is also a bias-risk zone: the criteria must be the posted requirements, never inferred proxies.\n\n(3) Phone screens — AUGMENT the paperwork: draft question guides from the role profile beforehand; summarize recruiter notes into the ATS afterwards. The conversation itself stays human.\n\n(4) Interview loops — AUGMENT logistics: brief packets for interviewers, collate feedback into a structured comparison. The evaluation is human judgment.\n\n(5) Offer decision — HUMAN ONLY. High-stakes, legally sensitive, and irreversible in candidate-experience terms. Claude may compile the data package that informs it; it must not recommend who to hire.\n\nHandoffs to document: recruiter reviews all AI rejections (step 2); hiring manager owns the decision record (step 5). Measure: time-per-screen and candidate-drop-off before vs after."}, {"who": "user", "text": "HR asked why Claude shouldn't just rank the candidates 1–200 — wouldn't that be faster?"}, {"who": "claude", "text": "Faster, and exactly the wrong step to automate. A ranking is a hiring judgment: it compounds any bias in the inputs, is hard to explain to a rejected candidate or an auditor, and in several jurisdictions triggers automated-decision rules. Structuring facts FOR human comparison is augmentation; producing the ordering IS the decision. Keep the decision human — that boundary is where responsible integration lives."}], "q": ["p16"], "links": ["4.2", "2.4"]},
    {"id": "4.5", "d": "d4", "title": "Communicate Claude's value and limitations to stakeholders", "concept": "Associates translate between the technology and the business: articulate value in the stakeholder's terms (hours saved, cycle time, quality lift — with measured numbers), and state limitations plainly (hallucination risk, training-data recency, context limits, judgment stays human). Credibility comes from naming both.", "antipattern": "Hype ('it eliminates the work') that shatters on the first hallucination — or reflexive doom ('it makes things up, avoid it') that forfeits real value. Both are communication failures, not technology facts.", "right": "Pair every value claim with its evidence and every limitation with its mitigation: 'Drafting time fell 60% in the pilot (n=45 docs). It can fabricate specifics, so citations are verified before use — that check is built into the workflow.'", "tip": "Exam answers that present measured value AND named limitations with mitigations beat pure advocacy, pure caution, and jargon-heavy technical explanations.", "analogy": "A good realtor's walkthrough: here's what the house does well, here's the foundation crack, here's what maintenance costs. Buyers trust the person who showed them the crack.", "pitfall": "One deck for every audience. Executives need outcomes and risk posture; the working team needs when-to-trust/when-to-override; legal needs data flows. Same facts, tailored framing (see lesson 2.5).", "chat": [{"who": "note", "text": "An associate must brief the executive committee after a successful pilot — including its one embarrassing failure."}, {"who": "user", "text": "Help me structure the exec briefing on our contract-review pilot. Results: review prep time down from 4.2h to 1.5h across 30 contracts. But in week 2, a draft summary invented a termination clause that wasn't in the contract — caught by the reviewing lawyer. Some execs will want to expand immediately; one is skeptical of AI entirely."}, {"who": "claude", "text": "Structure that serves both camps — value with evidence, limitation with mitigation:\n\n1. OUTCOME (30 seconds): 'Contract review prep dropped 64% — 2.7 hours saved per contract, ~81 hours over the pilot. Lawyer review time on substance stayed unchanged: the savings came from summarization and clause-location, not from replacing judgment.'\n\n2. THE FAILURE, TOLD BY US (this is the credibility move): 'In week 2 the tool fabricated a clause that didn't exist. Our reviewing lawyer caught it — which is the design working: every AI summary is checked against the source before it informs any decision. We treat the tool as a fast first-pass reader, never as the reader of record.'\n\n3. LIMITS AS OPERATING RULES: fabrication risk → verification step; no current-events knowledge → research mode or provided documents only; long-contract context limits → section-by-section processing.\n\n4. EXPANSION ASK: extend to NDA triage next (similar task shape, lower stakes), NOT to negotiation strategy (judgment work — stays human).\n\nFor your skeptic: lead with the failure story — it shows the safeguards are real, not theoretical."}, {"who": "user", "text": "Give me the two-sentence version for the CEO who'll read only the summary line."}, {"who": "claude", "text": "'The pilot cut contract-review prep 64% (81 hours saved / 30 contracts) while keeping every legal judgment with our lawyers. One fabricated clause in week 2 was caught by the built-in verification step — the safeguard we'd scale with it.'"}], "q": ["p17"], "links": ["2.5", "6.1"]},
    {"id": "5.1", "d": "d5", "title": "Configure Claude Projects with instructions and knowledge sources", "concept": "A Project packages durable context — custom instructions (role, tone, rules, output formats) plus knowledge sources (documents Claude consults in every chat) — so each new conversation starts already briefed. Instructions define HOW to work; knowledge defines WHAT to know.", "antipattern": "Projects as mere chat folders — no instructions, no knowledge — while still pasting the style guide into every chat; or dumping 40 documents in as knowledge 'just in case', drowning the relevant in the redundant.", "right": "Instructions: role, audience, tone, format rules, and hard constraints, written like a brief to a contractor. Knowledge: the curated few documents chats actually need — style guide, product facts, templates — kept current.", "tip": "Exam cue: 'the team repeats the same context in every conversation' → configure a Project with instructions + knowledge. Distractors suggest longer prompts, one shared mega-chat, or retyping context.", "analogy": "A new hire's welcome binder plus their job description. The job description (instructions) says how to behave and what good output looks like; the binder (knowledge) holds the reference material. Together they replace re-explaining the job every morning.", "pitfall": "Putting volatile facts in instructions (they belong in swappable knowledge docs) or durable rules in individual chats (they belong in instructions). Stable → instructions; changing → knowledge; one-off → the chat.", "chat": [{"who": "note", "text": "A content team lead sets up a Project for the company blog after months of re-pasting context."}, {"who": "user", "label": "Before", "text": "(every new chat) You write for our B2B logistics blog. Tone: expert but plain-spoken, no buzzwords. Audience: warehouse ops managers. Always end with one actionable takeaway. Our products are… [pastes 2 pages] Now, draft a post about dock scheduling."}, {"who": "claude", "text": "Here's a draft blog post on dock scheduling…\n\n(fine — but this setup ritual repeats in every chat, drifts as teammates paste older versions, and new writers don't know it exists)"}, {"who": "note", "text": "The fix — one Project, configured once, shared with the team:"}, {"who": "user", "label": "Project setup", "text": "Creating a 'Blog Content' Project. Instructions: 'You write for our B2B logistics blog. Audience: warehouse ops managers. Tone: expert, plain-spoken, no buzzwords. Posts are 800–1200 words, end with one actionable takeaway, and cite only facts from Project knowledge.' Knowledge: brand voice guide (PDF), product fact sheet (current version), two exemplar posts, SEO checklist. First task in this Project: draft a post about dock scheduling."}, {"who": "claude", "text": "Draft: 'The Hidden Cost of First-Come, First-Served Docks'\n\n(Opens with an ops-manager pain point, plain-spoken per instructions; product mentions match the fact sheet exactly; structure mirrors the exemplar posts; ends with an actionable takeaway; 1,050 words)\n\nEvery future chat in this Project starts from this same footing — teammates included. When the product sheet changes, swap the knowledge file once and every subsequent chat uses the new facts."}], "q": ["p18"], "links": ["5.3", "3.1"]},
    {"id": "5.2", "d": "d5", "title": "Manage uploaded knowledge and connectors (e.g., Google Drive, Gmail)", "concept": "Claude's knowledge about YOUR work arrives two ways: uploads (point-in-time snapshots — must be re-uploaded when the source changes) and connectors like Google Drive or Gmail (live access to current content, governed by permissions). Managing them means choosing the right mechanism, curating what's connected, and respecting data-sensitivity rules for everything shared.", "antipattern": "Uploading a pricing sheet once and trusting it for a year — decisions made on stale snapshots — or connecting an entire Drive 'for convenience', sweeping confidential folders into scope no one intended.", "right": "Stable reference docs → upload, with an owner and a review date. Frequently changing sources → connector, scoped to the specific folders needed. Before connecting anything: what's IN there, and is it cleared under your data policy?", "tip": "Exam cue: 'the document changes weekly' → connector (or a re-upload routine); 'Claude used outdated numbers' → the snapshot went stale; anything with personal or regulated data in a connector → policy and minimization first.", "analogy": "Photocopies versus a keycard to the records room. The photocopy (upload) was true the day you made it; the keycard (connector) always opens the current file — and comes with rules about which rooms you're allowed into.", "pitfall": "Forgetting uploads are frozen. If Claude cites a figure from Project knowledge, ask when that file was last replaced — 'it's in the Project' is not the same as 'it's current'.", "chat": [{"who": "note", "text": "A sales ops associate discovers quotes are being drafted from a stale price list."}, {"who": "user", "text": "A rep just sent a quote with June prices — we raised them August 1. The Project has our price list as knowledge. How is this happening?"}, {"who": "claude", "text": "Because the price list in Project knowledge is an UPLOAD — a snapshot from the day it was added, June 3 per its content. Uploads don't update themselves; I've been answering from a file that was true eleven weeks ago.\n\nTwo fixes:\n\nA) Re-upload routine: replace the file on a schedule, with a named owner. Works, but depends on a human remembering — the failure you just experienced.\n\nB) Connector: link the Google Drive folder where sales ops maintains the live price sheet. Chats then read the CURRENT file each time. Scope it to that one pricing folder — not the whole Drive — so nothing confidential rides along.\n\nGiven prices change monthly and quotes are money, B is the right mechanism. One governance check first: confirm the pricing folder contains no customer-specific negotiated rates that reps outside those accounts shouldn't see — connector scope is an access decision, not just a convenience."}, {"who": "user", "text": "Connected the pricing folder only. What should we do with the stale upload?"}, {"who": "claude", "text": "Delete it from Project knowledge now — if both exist, I may draw from either, and the stale copy can silently win. Then add one line to the Project instructions: 'Pricing comes ONLY from the connected Drive pricing folder; always state the sheet's effective date in any quote.' That last clause makes staleness visible to the rep instead of invisible in the quote."}], "q": ["p19"], "links": ["5.1", "6.2"]},
    {"id": "5.3", "d": "d5", "title": "Create effective system-level instructions", "concept": "System-level instructions (Project instructions and their org-level equivalents) are standing orders that apply to every conversation: role, audience, tone, format rules, boundaries, and escalation behavior. Good ones are specific, testable, and prioritized — they read like a brief, not a wish.", "antipattern": "Vibes-based instructions ('be professional and helpful, keep things concise-ish') that constrain nothing, contradict each other, or bury the one hard rule ('never quote prices') in paragraph six where it competes with fluff.", "right": "Write rules a stranger could apply and check: 'Always/Never' for hard constraints, concrete formats ('answers ≤ 150 words unless asked'), explicit escalation ('if asked about legal terms, direct to legal@ — do not draft'), hard rules first.", "tip": "On the exam, the best instruction option is specific and testable ('cite the policy doc section for every answer') — not the longest, and never 'tell it to be accurate and professional'.", "analogy": "A restaurant's standing kitchen rules posted on the wall — 'allergens always flagged, no substitutions without the chef, plating per the photo book'. They govern every order without being repeated to every cook every shift.", "pitfall": "Instruction sprawl. Every incident adds a rule until they conflict; behavior gets erratic. Prune on review — few, sharp rules beat many soft ones.", "chat": [{"who": "note", "text": "A support team's Project answers agents' policy questions — the instructions need a rewrite."}, {"who": "user", "label": "Weak instructions", "text": "Current Project instructions: 'You are a helpful assistant for our support team. Be professional, accurate and concise. Try to be consistent with our policies.' Agents complain answers vary wildly and once included a made-up refund exception. Rewrite these properly."}, {"who": "claude", "text": "The current instructions fail because none of them are checkable — 'accurate' and 'consistent' aren't rules, they're hopes. Rewrite, hard rules first:\n\n---\nROLE: You answer internal policy questions for support agents. You are not customer-facing.\n\nHARD RULES:\n1. Answer ONLY from the policy documents in Project knowledge. If the answer isn't there, say 'Not covered in policy docs' and name the closest section — never infer or invent policy.\n2. Cite the document and section for every answer (e.g., 'Refunds Policy §3.2').\n3. Refund exceptions, legal threats, and anything involving a named customer's data → 'Escalate to your team lead' — do not advise.\n\nFORMAT: ≤120 words. Rule first, citation second, edge cases third.\nTONE: Direct, neutral. No apologies, no filler.\n---\n\nEach rule is testable: an answer either carries a citation or it doesn't; a refund-exception question either got escalated or it didn't. That made-up exception becomes impossible to deliver silently — rule 1 forces 'not covered' instead."}, {"who": "user", "text": "Two months later: agents keep asking about the new EU return window, which isn't in the docs, and they say the 'no apologies' tone reads as rude in answers that deny a request. Update."}, {"who": "claude", "text": "Two surgical changes, no sprawl:\n1. Root cause of the EU questions is a KNOWLEDGE gap, not an instruction gap — upload the updated returns policy; the instructions already handle it once the doc exists.\n2. Tone rule amended: 'Direct and neutral; when denying or restricting, add one plain-language sentence explaining why.' Still testable — denial answers either carry the why-sentence or they don't.\n\nAnd prune check: no rules conflict, still 3 hard rules. Instructions stay few and sharp."}], "q": ["p20"], "links": ["5.1", "1.1"]},
    {"id": "5.4", "d": "d5", "title": "Inform, maintain, and update Claude configurations, knowledge sources, and instructions", "concept": "Configuration is a living system: knowledge goes stale, instructions drift from reality, and quiet failures accumulate. Maintenance means ownership (someone is responsible), triggers (policy changed → update the Project same week), review cadence, versioning of key docs, and telling users what changed.", "antipattern": "Set-and-forget: the Project that was excellent in March quietly answering from March's prices, March's policy, March's org chart in September — wrong with total confidence, and nobody assigned to notice.", "right": "Name an owner per Project. Tie updates to events ('policy revision published → replace knowledge doc within a week') plus a quarterly sweep: stale docs out, instructions tested against current reality, changelog note to the team.", "tip": "Exam scenarios where 'the Project gives outdated answers' are maintenance questions: the fix is update/replace the knowledge and review instructions — not 'the model degraded' and not 'add a longer prompt'.", "analogy": "First-aid kits in an office: someone owns restocking, checks expiry dates quarterly, and posts a note when the epinephrine moves. A kit nobody maintains is worse than none — it promises help it can't deliver.", "pitfall": "Updating documents but not instructions (or vice versa). A new returns policy PLUS an instruction still citing the old section numbers = confidently mixed signals. Update both, together.", "chat": [{"who": "note", "text": "A quarterly review of the customer-support Project, prompted by a bad answer."}, {"who": "user", "text": "An agent got told our warranty is 12 months — it's been 24 since the July policy change. Audit this Project's setup with me: what's stale and how do we keep this from recurring?"}, {"who": "claude", "text": "Audit of Project knowledge and instructions:\n\nSTALE:\n• 'Warranty & Returns Policy v3.pdf' — superseded by v4 in July (the 12-month answer came from here)\n• 'Escalation contacts.xlsx' — lists two employees who left in Q2\n• Instructions cite 'Policy §5 for warranty' — v4 moved warranty to §7\n\nCURRENT: product fact sheet (connected via Drive — updates itself), tone rules, format rules.\n\nRecurrence prevention — a maintenance contract for this Project:\n1. OWNER: name one person (you?) accountable for Project accuracy\n2. EVENT TRIGGERS: policy publication → knowledge swap within 5 business days; org changes → contacts file same week\n3. QUARTERLY SWEEP: every doc gets checked or replaced; instructions tested with 5 known-answer questions ('what's the warranty?' should say 24 months, §7)\n4. VERSION VISIBLY: filenames carry version + effective date ('Warranty Policy v4 — eff. 2026-07-01') so staleness is inspectable\n5. CHANGELOG: one-line note to the team channel on every update, so agents know the Project moved with the policy"}, {"who": "user", "text": "Do the swap and the instruction fix now; I'll take ownership and the quarterly sweep."}, {"who": "claude", "text": "Done conceptually — v4 replaces v3 in knowledge, instructions now cite §7, contacts file flagged for HR's current list. First test question against the updated setup: 'What's our warranty period?' → '24 months (Warranty Policy v4, §7, effective July 2026).' The citation-with-version habit means the NEXT staleness will announce itself instead of hiding."}], "q": ["p21"], "links": ["5.2", "7.1"]},
    {"id": "6.1", "d": "d6", "title": "Identify appropriate and inappropriate use cases", "concept": "Fit for AI is judged on stakes, reversibility, verifiability, and data sensitivity. Strong fits: drafting, summarizing, analysis support, ideation — human-reviewed, low-blast-radius work. Poor fits (without controls): final decisions about people, unreviewed external/legal/medical output, and anything your policy or regulation excludes.", "antipattern": "Judging fit by capability alone: 'it CAN write performance reviews / diagnose the symptom / decide the claim, so let it.' Capability is necessary, never sufficient — consequences and accountability decide.", "right": "Screen each use case: What happens if it's wrong? Who reviews before impact? Is the data allowed here? Is a human accountable for the outcome? Green-light drafting/summarizing/analyzing under review; gate or refuse autonomous high-stakes decisions.", "tip": "Exam options that use AI for drafts/analysis WITH human judgment retained beat both 'fully automate the decision' and 'never use AI'. Look for who holds accountability in each option.", "analogy": "An intern policy. Interns draft memos, do research, and prepare comparisons — they don't sign contracts, decide promotions, or speak to the press. Not because they lack talent; because accountability and stakes sit elsewhere.", "pitfall": "The creep from assist to decide. 'Claude drafts the rejection letters' quietly becomes 'Claude decides the rejections'. Re-screen whenever the AI's role in a workflow expands.", "chat": [{"who": "note", "text": "A team lead brainstorms AI use cases for the quarter — some fit, some don't."}, {"who": "user", "text": "Screen these four use-case ideas: (1) summarize weekly customer feedback into themes, (2) draft performance-review paragraphs for my directs based on my bullet notes, (3) auto-respond to inbound insurance claims under $500, (4) prep first drafts of our RFP responses."}, {"who": "claude", "text": "Screening on stakes, review, data, and accountability:\n\n(1) Feedback summarization — STRONG FIT. Low stakes, easily spot-checked against raw feedback, no individual decisions. Just anonymize any customer identifiers per policy.\n\n(2) Performance-review drafting — CONDITIONAL. Drafting FROM YOUR assessments (your bullets, your judgments) with you editing and owning every word: acceptable in many orgs. But check policy first — some prohibit AI in personnel evaluation entirely; and personnel data is sensitive. The judgment must remain visibly yours; if the AI starts characterizing performance beyond your notes, that's the creep line.\n\n(3) Auto-responding to claims — POOR FIT as stated. That's an autonomous, binding decision affecting people's money — high stakes, no review before impact, likely regulated (automated-decision rules). Refactor: Claude TRIAGES and drafts, a licensed adjuster approves. The decision stays human.\n\n(4) RFP first drafts — STRONG FIT. Substantial drudgery reduction; inherently reviewed (nobody submits an RFP unread); facts checked against your knowledge base before submission.\n\nPattern: 1 and 4 assist judgment; 3 as stated replaces it. That's the line."}, {"who": "user", "text": "For (3), sales says competitors auto-settle small claims instantly and we're losing customers to slow payouts."}, {"who": "claude", "text": "Then solve the speed problem without ceding the decision: Claude pre-processes each claim in seconds — completeness check, policy-coverage lookup, fraud-signal flags, and a recommended disposition with reasons — queued for an adjuster who approves with one click. Payout in minutes, but a human accountably decides. If the business later wants true auto-settlement, that's a formal governance decision with legal review — not a workflow tweak an associate ships."}], "q": ["p22"], "links": ["6.3", "2.4"]},
    {"id": "6.2", "d": "d6", "title": "Apply data sensitivity, regulatory, and privacy considerations", "concept": "Before data goes into any AI tool, classify it: public, internal, confidential, regulated (PII, PHI, PCI…). Policy determines what each class permits. The working defaults: minimize (share only what the task needs), anonymize or redact identifiers when the analysis doesn't need them, and when policy restricts the data — transform the task, don't sneak the data.", "antipattern": "Uploading the raw customer spreadsheet 'because the analysis is internal', or telling the tool 'don't retain this' as if an instruction to the model satisfied a policy control on data handling.", "right": "Check the classification, then minimize: strip names, account numbers, and contact details when trends are the goal — the analysis usually survives anonymization intact. If it genuinely needs identifiers, that's an approval conversation, not a workaround.", "tip": "Official sample question 3 is this lesson: remove/anonymize regulated identifiers before uploading, consistent with policy. 'Upload as-is (it's internal)', 'instruct Claude not to retain it', and 'abandon the task' are the three distractor shapes.", "analogy": "Mailing documents: a flyer goes in any envelope; medical records require sealed, tracked, authorized delivery. The content class — not convenience — dictates the handling.", "pitfall": "Believing anonymization is just deleting the name column. Combinations (zip + birthdate + role) can re-identify; when stakes are high, involve whoever owns privacy review.", "chat": [{"who": "note", "text": "A project manager wants churn trends from a spreadsheet full of regulated personal data. (This mirrors official sample question 3.)"}, {"who": "user", "label": "Risky request", "text": "I'm uploading our cancellations spreadsheet — customer names, emails, account numbers, plan, region, cancel date, and stated reason. Find me the churn patterns by region and plan for the ops review."}, {"who": "claude", "text": "Before you upload: look at what the analysis actually needs. Your question is about patterns by REGION, PLAN, DATE, and REASON — names, emails, and account numbers contribute nothing to it, and they're exactly the fields your data policy likely classifies as regulated personal data.\n\nThe compliant path costs you nothing analytically:\n1. Copy the sheet\n2. Delete the name, email, and account-number columns\n3. If you need to track repeat cancellations, replace account numbers with sequential IDs (C001, C002…) — a mapping only your team keeps, outside this tool\n4. Upload the minimized version\n\nSame patterns, same ops review, zero exposed identifiers. Note what does NOT work as a control: uploading everything and instructing me 'don't retain it' — my instructions aren't a data-handling control your policy recognizes. And abandoning the analysis is unnecessary — minimization enables it."}, {"who": "user", "label": "Fixed", "text": "Minimized version uploaded — IDs, plan, region, dates, reasons only."}, {"who": "claude", "text": "Analysis on the minimized data:\n\n• EU-South churn is 2.3× baseline, concentrated in the Starter plan within 60 days of onboarding — reasons cluster on 'missing local-language support'\n• Enterprise churn is flat, but three repeat-cancel IDs (C044, C112, C189) show a downgrade→cancel path worth an outreach play\n• Price-related reasons are stable QoQ — the June increase isn't the driver\n\nEvery finding, no personal data at risk. If ops later needs to contact specific at-risk customers, hand the flagged IDs to the team that holds the mapping — re-identification happens inside your controlled system, not here."}], "q": ["q3"], "links": ["6.3", "5.2"]},
    {"id": "6.3", "d": "d6", "title": "Follow organizational AI policies and governance standards", "concept": "Your organization's AI policy — approved tools, permitted data classes, required disclosures, mandatory review gates — is the operating boundary. Associates work within it, route exceptions through the proper channel, and treat 'the policy is inconvenient' as a reason to engage governance, never a reason to route around it.", "antipattern": "Shadow AI: pasting company data into a personal account on an unapproved tool because it's faster, assuming 'nobody said I couldn't', or shipping AI-generated client work without the disclosure the policy requires.", "right": "Know the policy before the workflow: which tools are sanctioned, what data may they touch, what needs human sign-off, what must be disclosed. When a rule blocks real value, document the case and request an exception through governance.", "tip": "In exam scenarios, options that comply-then-escalate ('follow policy; raise the gap with governance') beat options that bypass, ignore, or unilaterally reinterpret the policy — even when the bypass is framed as harmless.", "analogy": "Aviation checklists. Pilots don't skip items because today's flight seems routine — and when a checklist genuinely doesn't fit the aircraft, they file to change the checklist. They don't freelance at 30,000 feet.", "pitfall": "Assuming silence means permission. If the policy doesn't address your new use case, that's a question for the AI governance owner — undefined is not approved.", "chat": [{"who": "note", "text": "An analyst hits a policy wall a week before a deadline."}, {"who": "user", "label": "Tempted", "text": "Our AI policy only approves Claude for internal documents — client deliverables need a senior manager's review of any AI-assisted work, and mine is on leave until after my deadline. Honestly I could just not mention that Claude helped draft it. It's my analysis anyway — I'd review it myself. Thoughts?"}, {"who": "claude", "text": "Don't do the quiet route — walk through what it actually is: the policy makes AI-assistance in client work a disclosed, reviewed activity. Omitting the disclosure isn't a shortcut, it's a policy violation with your name on it, and it converts a manageable scheduling problem into an integrity problem that surfaces at the worst times (client audit, quality dispute, or a colleague simply asking how you drafted it so fast).\n\nYour actual options, all boring and safe:\n1. The policy names a ROLE, not a person — is there an acting/covering senior manager? Usually yes.\n2. Ask your manager's manager to designate a reviewer — a two-line email, resolved today.\n3. Ask the client-facing deadline owner for 48 hours, citing internal QA.\n4. If none work: deliver the analysis WITHOUT AI assistance on the client-facing artifact, using Claude only for the internal prep the policy already permits.\n\nAnd afterwards, file the real finding: the policy has a single-point-of-failure on one reviewer. That's a governance improvement request — you'd be fixing the rule instead of breaking it."}, {"who": "user", "text": "Option 2 worked — the director will review it Thursday. Draft the governance suggestion too."}, {"who": "claude", "text": "To: AI Governance owner\nSubject: Policy gap — reviewer coverage for AI-assisted client work\n\n'Section 4.2 requires senior-manager review of AI-assisted client deliverables but names no backup when the reviewer is unavailable. This week that nearly blocked a client deadline (resolved via ad-hoc designation by the director). Request: amend 4.2 to name a covering-reviewer rule, so compliance never competes with delivery.'\n\nCompliant this week, better policy next quarter — that's how the boundary is supposed to move."}], "q": ["p23"], "links": ["6.2", "6.4"]},
    {"id": "6.4", "d": "d6", "title": "Understand the ethical implications of AI usage", "concept": "Beyond policy compliance sit the questions policy can't fully write down: bias (whose patterns did the data learn?), transparency (do affected people know AI was involved?), accountability (a human owns every consequential output), and honesty about AI's role in your work. Ethical use means asking 'should we?' after 'can we?' — especially where outputs touch people.", "antipattern": "'The AI decided' as an accountability shield; presenting wholly AI-written analysis as your independent expert judgment; or deploying a system that quietly disadvantages a group because nobody looked at the outputs across groups.", "right": "Bias: inspect outputs across groups before trusting a people-affecting workflow. Transparency: disclose AI involvement where it matters (clients, affected employees, published work). Accountability: every consequential output has a human owner who reviewed it and answers for it.", "tip": "Exam options embodying disclosure, human accountability, and bias-checking beat options that hide AI involvement, defer moral judgment to the tool, or treat 'technically allowed' as 'ethically fine'.", "analogy": "A powerful lens: it lets you see more, and it distorts at the edges. An ethical user knows where the distortion lives, tells people they're looking through a lens, and never blames the lens for what they chose to do with it.", "pitfall": "Treating ethics as a launch-day checkbox. Bias and drift show up in operation — revisit outcomes over time, not just intentions at kickoff.", "chat": [{"who": "note", "text": "A marketing manager reviews an AI-assisted campaign targeting model before launch."}, {"who": "user", "text": "We used Claude to help segment customers for our premium credit-card campaign, based on past approval patterns. Before launch — walk me through the ethical review, not just the legal one."}, {"who": "claude", "text": "Four questions, in order of bite:\n\n1. BIAS — 'past approval patterns' is the loaded phrase. If historical approvals skewed by neighborhood, age, or proxies for protected classes, a segmentation learned from them reproduces that skew with perfect confidence. Check: compare the campaign's include/exclude rates across demographics you're able to observe. If certain groups vanish from 'premium eligible', you've automated yesterday's bias.\n\n2. TRANSPARENCY — would customers be surprised to learn how they were selected (or silently excluded)? Surprise is a decent ethics smoke alarm. Marketing selection is normal; what people don't expect is exclusion from OFFERS of credit via opaque profiling.\n\n3. ACCOUNTABILITY — who signs off on the segment list? If the answer is 'the model produced it', that's the anti-pattern. A named human should review the segmentation logic and own the outcome.\n\n4. HONESTY INTERNALLY — when you present results, the deck should say the segmentation was AI-assisted and how it was checked. Your leadership can't govern what it doesn't know exists.\n\nNote: much of this may ALSO be regulated (credit marketing often is) — but you asked the right question, because 'legal' would only tell you the floor."}, {"who": "user", "text": "The demographic comparison shows two zip-code clusters almost entirely excluded — both historically underbanked areas."}, {"who": "claude", "text": "That's the finding that stops a launch. The model has likely learned redlining's echo from the historical data. Path forward: (1) don't ship this segmentation; (2) rebuild on forward-looking, behavior-based criteria (stated interest, product usage) rather than inherited approval patterns; (3) bring compliance in — in credit contexts this pattern can be unlawful, not merely unfair; (4) document the catch — it's the strongest possible case for keeping human ethical review in every AI-assisted workflow that touches people."}], "q": ["p24"], "links": ["6.1", "4.4"]},
    {"id": "7.1", "d": "d7", "title": "Identify, diagnose, and resolve issues with underperforming prompts or poor outputs", "concept": "Debug prompts like a mechanic, not a gambler: reproduce the failure, classify it (missing context? ambiguous ask? wrong format? stale knowledge? task too big? wrong tool/model?), fix the diagnosed cause, and re-test on the same input. Each failure type has a matching repair.", "antipattern": "Re-running the identical prompt hoping for different output, bolting 'be more accurate and detailed!!' onto it, or abandoning the tool — all without ever naming what KIND of failure occurred.", "right": "Triage first: wrong facts → context/knowledge gap (add sources); wrong focus → ambiguity (state the goal and audience); wrong shape → format unstated (specify it); ignores instructions in a long chat → context overflow (summarize + restart); shallow on hard reasoning → task/model mismatch (decompose or upgrade).", "tip": "Exam troubleshooting stems describe symptoms. Match symptom → cause → minimal fix. Distractors re-roll, over-engineer, or swap tools without a diagnosis.", "analogy": "A car that won't start. The gambler turns the key harder and buys a new car. The mechanic asks: fuel, battery, or starter? — because each has a different fix and checking is cheap.", "pitfall": "Fixing two variables at once. Change the prompt OR the knowledge OR the model, then re-test — simultaneous changes hide which fix worked, so the lesson is lost for next time.", "chat": [{"who": "note", "text": "An analyst's weekly KPI commentary prompt started producing junk."}, {"who": "user", "label": "Symptom report", "text": "My weekly prompt — 'Write the KPI commentary for the ops dashboard from the attached export' — worked fine for months. The last two weeks it invents targets we don't have and comments on metrics that aren't in the export. Diagnose before you fix."}, {"who": "claude", "text": "Two distinct symptoms — let's classify each:\n\nSYMPTOM 1: 'invents targets we don't have' → fabrication filling a CONTEXT GAP. The prompt says 'commentary' but never provides targets, so plausible ones get invented. It 'worked for months' likely because earlier exports included a target column — did the export format change recently?\n\nSYMPTOM 2: 'comments on metrics not in the export' → same root family: the task is underspecified about scope, so general KPI knowledge leaks in.\n\nDiagnosis test (cheap, one run): re-run last week's export with one added line — 'Comment ONLY on metrics present in the export. Targets are in column D; if column D is empty, write 'no target set' rather than inferring one.' If both symptoms vanish, confirmed: this was a context + scope-specification failure, not model degradation."}, {"who": "user", "text": "Confirmed — export format changed 3 weeks ago, the target column was dropped. Your test line fixed both symptoms. Make the fix permanent."}, {"who": "claude", "text": "Permanent repair, addressing cause not symptom:\n1. Restore targets as INPUT: ask ops to re-include column D, or attach the targets sheet alongside the export\n2. Harden the prompt: 'Scope: ONLY metrics in the export. Targets: ONLY from column D / targets sheet — never inferred. If a target is missing, say so.'\n3. Add a canary: end each run with 'List any metric you commented on that lacks a source row' — an empty list is your weekly health check.\n\nOne diagnosed cause, one targeted fix, re-tested on the same input — and a tripwire so the next format change announces itself."}], "q": ["p25"], "links": ["1.3", "3.4"]},
    {"id": "7.2", "d": "d7", "title": "Adjust approach based on feedback and results", "concept": "Treat AI workflows as feedback systems: collect signals (edit distance from final versions, user corrections, spot-check results, complaint themes), read what they say about the setup, and adjust the prompt, knowledge, format, or process — then keep watching. One-time setup is a myth; calibration is the job.", "antipattern": "Shipping a workflow and never looking at what users do with its outputs — or the opposite reflex: rebuilding everything after one bad anecdote instead of checking whether it's a pattern.", "right": "Instrument lightly: where do humans edit the drafts most? which questions come back? what do spot-checks catch? Aggregate before acting — patterns get fixes, anecdotes get logged. Adjust one lever, re-measure.", "tip": "Exam answers that gather feedback, find the pattern, and adjust the specific failing element beat 'rebuild from scratch', 'ignore it', and 'add a disclaimer'.", "analogy": "A thermostat, not a fire-and-forget heater. It works because it keeps measuring the room and correcting. A heater with no sensor is 'set up correctly' right until the room is an oven.", "pitfall": "Optimizing for the loudest complaint. A senior stakeholder's one-off gripe and a systematic 30% edit-rate are different classes of signal; rank by frequency × impact, not volume of the complainer.", "chat": [{"who": "note", "text": "A proposal-drafting workflow has been live for six weeks — time to read the signals."}, {"who": "user", "text": "Six weeks of our Claude proposal-drafting workflow. Feedback so far: sales edits the pricing section heavily in 9 of 12 proposals; two reps say the tone is 'too formal for startups'; one VP hated one proposal ('unusable') but couldn't say why; the exec summaries are apparently loved. What do we change?"}, {"who": "claude", "text": "Rank the signals before touching anything:\n\n1. PRICING EDITS — 9/12 is a SYSTEMATIC signal, highest priority. Diagnose the edits: are reps fixing wrong numbers (→ stale pricing knowledge — check when the price file was last updated) or re-structuring how pricing is presented (→ template/instruction gap)? Pull three edited versions and diff them against the drafts; the edits will tell you which.\n\n2. TONE FOR STARTUPS — pattern (two independent reps, same theme). Fix is cheap: add an audience switch to the prompt/Project — 'if prospect is <100 employees, use direct, informal register; drop the compliance boilerplate to an appendix.'\n\n3. VP ANECDOTE — n=1 with no failure description. Don't rebuild anything for it; log it, and ask the VP's team for the specific proposal to inspect. If it matches pattern 1 or 2, it's already covered.\n\n4. EXEC SUMMARIES — positive signal: change NOTHING there, and say so explicitly in any revision notes so nobody 'improves' the part that works.\n\nOne lever at a time: fix pricing first, re-measure the edit rate for two weeks, then tone."}, {"who": "user", "text": "Diffed the pricing edits — reps are correcting discount tiers that changed in a June sales-ops memo. The Project's pricing doc predates it."}, {"who": "claude", "text": "So the workflow was drafting from a stale snapshot — a knowledge-maintenance failure surfacing as an editing burden (lesson 5.4's territory). Swap in the current tier sheet, add sales-ops memos to the update-trigger list, and re-measure: pricing edit-rate should collapse from 9/12 toward ~2/12 (genuine deal-specific tailoring). If it doesn't, the diagnosis was incomplete — back to the diffs."}], "q": ["p26"], "links": ["7.1", "4.3"]},
    {"id": "7.3", "d": "d7", "title": "Optimize workflows for efficiency and effectiveness", "concept": "Once a workflow WORKS, make it economical: cut redundant steps and re-pasted context (Projects/templates), batch similar items instead of one-at-a-time chats, right-size the model per step, stop over-polishing internal drafts, and measure end-to-end time — including the human review — not just the AI seconds.", "antipattern": "Optimizing the wrong denominator: shaving AI response seconds while every output still waits two days for one over-loaded reviewer — or polishing internal status notes to publication grade at 3× the cost.", "right": "Profile the whole flow: where do items wait? what's re-done every time? what quality level does each output actually need? Then: template the repeated, batch the similar, downsize models where review nets are strong, and fix the human bottleneck the numbers point at.", "tip": "Exam optimization answers keep quality safeguards while removing redundancy (batching, templates, right-sized models, fewer handoffs). Distractors remove the safeguards or optimize a step that wasn't the bottleneck.", "analogy": "A commercial kitchen during service: same dishes, but mise en place ready (persistent context), orders fired in batches, the sous-chef on prep and the head chef only on finishing (model right-sizing). The food isn't better — it's the same food, sustainably faster.", "pitfall": "Efficiency that silently drops effectiveness — batching so aggressively or downsizing so far that error rates climb past what the review step absorbs. Optimize with the quality metric on the dashboard, not after it.", "chat": [{"who": "note", "text": "A team's content-localization workflow works — but costs too much time per item."}, {"who": "user", "text": "Our product-update localization flow works but feels heavy. Per update: writer drafts in a chat (re-pasting the glossary every time), Claude adapts it for 5 regions one-by-one in 5 separate chats, then our one bilingual reviewer checks all 5 — she's a 2-day bottleneck. ~20 updates/month. Optimize it."}, {"who": "claude", "text": "Profile first — where the ~non-AI time goes: re-pasted setup (×20/month), five sequential chats per item (×20), and a single human reviewer absorbing 100 region-variants a month. Now the levers:\n\n1. KILL REDUNDANT CONTEXT: 'Localization' Project — glossary, tone rules per region, and banned-terms list as knowledge + instructions. Saves the paste ritual on every one of ~120 chats/month.\n\n2. BATCH THE SIMILAR: one chat per update produces all 5 regional variants in a single structured pass ('output a section per region'). 100 chats → 20.\n\n3. RIGHT-SIZE QUALITY PER OUTPUT: these are product updates (internal-ish, templated), not brand campaigns — a mid-tier model with the Project's glossary is the right spend; save top-tier for the quarterly launch posts.\n\n4. THE REAL BOTTLENECK IS THE REVIEWER: don't remove her — refocus her. Have Claude self-annotate each variant with the 3 riskiest translation choices it made ('idiom replaced', 'regulatory term — verify'). She reviews flagged items deeply and spot-checks the rest, instead of reading everything cold. 2 days → hours, with the safety net intact.\n\nProjected: ~60% cycle-time cut, review quality signal IMPROVES (attention goes where risk is)."}, {"who": "user", "text": "And how do we make sure the batching and cheaper model don't quietly degrade quality?"}, {"who": "claude", "text": "Put the quality metric on the dashboard BEFORE switching: track reviewer correction-rate per variant for the current setup (baseline), then run the optimized flow in parallel for two weeks and compare. Accept the change only if corrections stay within the baseline band. Optimization without a quality gauge isn't optimization — it's cost-cutting with the lights off."}], "q": ["p27"], "links": ["3.3", "5.1"]},
  ];

  const scenarios = [{"id": "s1", "n": 1, "title": "Product Launch Content Pipeline", "domains": ["d1", "d2", "d3"], "summary": "A marketing team turns one launch brief into a full content suite — decomposed into steps, drafted per audience, fact-checked before anything ships, and delivered in the right formats.", "steps": [{"t": "Brief as prompt", "d": "Audience, tone, constraints, and format stated up front.", "task": "1.1"}, {"t": "Decompose the suite", "d": "Blog → email → social → FAQ as sequenced, reviewed steps.", "task": "1.2"}, {"t": "Audience variants", "d": "One fact set adapted for execs, customers, and press.", "task": "2.5"}, {"t": "Verify the claims", "d": "Every stat and product claim checked against the fact sheet.", "task": "2.3"}, {"t": "Right formats", "d": "Artifacts for the evolving docs, tables for the channel plan.", "task": "2.6"}, {"t": "Right model", "d": "Fast model for social variants; capable model for the launch post.", "task": "3.3"}]}, {"id": "s2", "n": 2, "title": "Ops Process Redesign with a Claude Project", "domains": ["d4", "d5", "d7"], "summary": "An operations lead maps a slow onboarding process, uses Claude to find the bottlenecks, validates with the process owners, and ships the redesign backed by a maintained Project.", "steps": [{"t": "Analyze the process", "d": "Bottlenecks, redundancies, and handoff risks from the step map.", "task": "4.2"}, {"t": "Validate with owners", "d": "Documented process ≠ real process — humans confirm dependencies.", "task": "4.1"}, {"t": "Project setup", "d": "SOPs and templates become instructions + knowledge.", "task": "5.1"}, {"t": "Integrate the steps", "d": "AI drafts and summarizes; humans keep approval gates.", "task": "4.4"}, {"t": "Measure and adjust", "d": "Before/after cycle time; feedback drives the next iteration.", "task": "7.2"}]}, {"id": "s3", "n": 3, "title": "Compliance-Safe Customer Data Analysis", "domains": ["d6", "d2", "d1"], "summary": "A PM needs churn insights from a spreadsheet full of regulated personal data — the analysis proceeds through minimization, policy compliance, verified findings, and a clean escalation boundary.", "steps": [{"t": "Classify the data", "d": "Names and account numbers are regulated — policy decides handling.", "task": "6.2"}, {"t": "Minimize, then upload", "d": "Identifiers stripped; sequential IDs preserve repeat-analysis.", "task": "6.2"}, {"t": "Policy check", "d": "Approved tool, permitted data class, documented approach.", "task": "6.3"}, {"t": "Analysis prompt", "d": "Explicit criteria: patterns by region, plan, and stated reason.", "task": "1.4"}, {"t": "Verify the findings", "d": "Spot-check claimed patterns against the raw rows.", "task": "2.1"}, {"t": "Escalate re-identification", "d": "Contacting flagged customers happens in controlled systems.", "task": "2.4"}]}, {"id": "s4", "n": 4, "title": "Executive Communications Pipeline", "domains": ["d1", "d2", "d5"], "summary": "A chief-of-staff workflow: one incident, three audiences, zero unverified claims — powered by a comms Project with standing instructions and iterated to the executive's voice.", "steps": [{"t": "Comms Project", "d": "Voice guide, org facts, and format rules configured once.", "task": "5.3"}, {"t": "Draft by task type", "d": "Analysis mode for the briefing; drafting mode for the notes.", "task": "1.4"}, {"t": "Audience adaptation", "d": "Exec summary, all-hands note, and board line from one source.", "task": "2.5"}, {"t": "No added claims", "d": "Adaptation never invents reassurance the source doesn't support.", "task": "2.2"}, {"t": "Iterate to voice", "d": "Anchored feedback: keep structure, match the exec's register.", "task": "1.3"}]}, {"id": "s5", "n": 5, "title": "Competitive Research with Research Mode", "domains": ["d3", "d2", "d4"], "summary": "A strategy associate builds a competitor briefing on current, cited information — research mode for freshness, source verification before circulation, and a stakeholder-ready synthesis.", "steps": [{"t": "Feature fit", "d": "Current events need research mode, not training-data recall.", "task": "3.1"}, {"t": "Scoped research prompt", "d": "Named competitors, time window, and sourcing requirements.", "task": "1.1"}, {"t": "Verify citations", "d": "Claimed announcements checked at the cited sources.", "task": "2.3"}, {"t": "Synthesize for decision", "d": "Findings organized into a comparison the exec team can act on.", "task": "2.6"}, {"t": "Value and limits", "d": "Briefing states freshness bounds and what wasn't verifiable.", "task": "4.5"}]}, {"id": "s6", "n": 6, "title": "Rescuing an Underperforming Workflow", "domains": ["d7", "d3", "d5"], "summary": "A once-good reporting workflow has degraded — diagnosis separates prompt, knowledge, and context failures; targeted fixes and a feedback loop bring it back cheaper than it started.", "steps": [{"t": "Reproduce and classify", "d": "Fabricated targets → context gap; scope drift → underspecification.", "task": "7.1"}, {"t": "Fix the knowledge", "d": "Stale snapshot replaced; update triggers assigned an owner.", "task": "5.4"}, {"t": "Restart the context", "d": "Summarize the mega-chat; durable constraints move to the Project.", "task": "3.4"}, {"t": "Adjust from feedback", "d": "Edit-rate patterns prioritized over loud anecdotes.", "task": "7.2"}, {"t": "Optimize the flow", "d": "Batching, templates, and right-sized models — quality gauge on.", "task": "7.3"}]}];
  const questions = [{"id": "q1", "task": "2.3", "domain": "d2", "prompt": "An associate asks Claude to summarize a new regulation, and Claude produces a confident summary citing a specific subsection number. Before sending the summary to the compliance team, what is the most appropriate action?", "options": ["Verify the cited subsection against the official regulation text before sharing.", "Reword the summary to sound more formal, then send it.", "Send it as-is, since Claude expressed high confidence.", "Ask Claude to rate its own confidence and send it if the rating is high."], "answer": 0, "why": "Language models can fabricate specific-looking details such as citation numbers — a hallucination. Validating factual claims, especially citations bound for a compliance audience, against an authoritative source is the diligence step required. Self-reported confidence is not a reliable accuracy signal, and reformatting does not address correctness."}, {"id": "q2", "task": "3.3", "domain": "d3", "prompt": "An associate needs to generate a high volume of short customer-reply drafts where speed and cost matter more than deep reasoning. Which choice best fits the task?", "options": ["Disable all product features to reduce cost.", "Use a faster, lower-cost model suited to straightforward, high-volume tasks.", "Switch to a different AI platform.", "Use the most capable, highest-cost model for every reply to maximize quality."], "answer": 1, "why": "Aligning model selection with task requirements means matching a faster, lower-cost model to straightforward, high-volume work, reserving the most capable model for complex reasoning. Always using the top model wastes the cost and latency budget; disabling features or switching platforms does not address the trade-off."}, {"id": "q3", "task": "6.2", "domain": "d6", "prompt": "A project manager wants to upload a spreadsheet containing customer names and account numbers so Claude can analyze trends. Organizational policy restricts sharing regulated personal data. What is the most appropriate action?", "options": ["Upload the file but instruct Claude not to retain it.", "Remove or anonymize the personal identifiers before uploading, consistent with policy.", "Upload the file as-is, since the analysis is internal.", "Skip the analysis entirely."], "answer": 1, "why": "Applying data-sensitivity and privacy safeguards means redacting or anonymizing regulated identifiers before use, so the analysis can proceed without exposing protected data. Uploading as-is violates policy; instructing the model not to retain data does not satisfy the policy control; and abandoning the task is unnecessary when anonymization enables it."}, {"id": "p1", "task": "1.1", "domain": "d1", "prompt": "A marketing associate asks Claude to 'summarize this report' and receives an accurate but generic 600-word summary that is useless for their 5-minute leadership briefing. What is the most effective revision?", "options": ["Run the same prompt several times and combine the best parts of each summary.", "Switch to a more capable model, since the summary quality was too low.", "Ask Claude to 'be more detailed and professional' and regenerate.", "State the audience, purpose, focus areas, length, and format in the prompt (e.g., '5 bullets for the COO, focused on risks and renewal impact')."], "answer": 3, "why": "The output was generic because the requirements — audience, purpose, focus, length, format — existed only in the associate's head. Effective prompts state them explicitly. Vague quality adjectives, regenerate-and-hope, and a bigger model all fail to supply the missing requirements."}, {"id": "p2", "task": "1.2", "domain": "d1", "prompt": "An operations lead needs a full analysis-and-recommendation pack for a warehouse migration: risks, timeline, and comms plan. What is the most reliable way to get a high-quality result from Claude?", "options": ["Chain the three prompts automatically so each output flows into the next without interruption.", "Break the work into sequenced steps (risks, then timeline, then comms plan), reviewing each output before it feeds the next step.", "Write one very detailed prompt requesting all three deliverables at once so nothing is lost between steps.", "Ask for all three deliverables in one prompt, then regenerate until the combined output looks right."], "answer": 1, "why": "Complex deliverables degrade in single mega-prompts, and errors in early parts poison later ones. Decomposition with a human checkpoint between steps keeps each output verifiable and grounds the next step in reviewed material. Chaining without review is the mega-prompt failure with extra steps."}, {"id": "p3", "task": "1.3", "domain": "d1", "prompt": "Claude's first draft of a policy announcement has the right structure but the wrong tone and too much length. The associate replies 'make it better' and gets a completely different draft — losing the structure that worked. What should they have done instead?", "options": ["Accept the first draft and edit it manually, since iteration changes too much.", "Regenerate several drafts and pick the best one.", "Give anchored, directional feedback: keep the structure, halve the length, change the tone to acknowledge the unpopular change, and say why.", "Start a new chat and rewrite the original prompt from scratch."], "answer": 2, "why": "Effective iteration names what to keep and what to change, with direction. Undirected feedback ('make it better') changes everything, including the good parts. Restarting or manual-only editing forfeits the model's ability to converge quickly when given specific feedback."}, {"id": "p4", "task": "1.4", "domain": "d1", "prompt": "An HR lead wants to explore ways to improve onboarding and asks Claude 'What is the best way to improve our onboarding process?' — getting one safe, generic recommendation. What went wrong?", "options": ["The model is too small for creative work; a more capable model would list more options.", "The prompt used an analysis shape for a brainstorming task; asking for many unfiltered, diverse ideas with judgment deferred would fit the task type.", "Nothing — a single best-practice answer is the correct output for this request.", "The prompt was too short; adding company background would produce more ideas."], "answer": 1, "why": "Brainstorming needs divergent prompting — quantity, variety, no premature filtering — while 'what is the best way' invites convergence to one answer. Matching prompt shape to task type (analysis, research, drafting, brainstorming) is the skill being tested; model size and prompt length are not the issue."}, {"id": "p5", "task": "2.1", "domain": "d2", "prompt": "Claude produces a fluent, well-formatted summary of a quarterly spreadsheet for a team update. What is the most appropriate evaluation before using it?", "options": ["Check that the tone and formatting are appropriate for the team audience.", "Have Claude regenerate the summary and compare whether the two versions agree.", "Verify each figure against the source spreadsheet AND check the summary covers everything the request asked for, including what it silently omitted.", "Ask Claude whether it is confident in the summary and proceed if it says yes."], "answer": 2, "why": "Evaluation is two questions: is what's present accurate (check against the source), and is anything missing (check against the request)? Fluency and formatting are not accuracy signals, self-reported confidence is unreliable, and two generations can agree on the same error."}, {"id": "p6", "task": "2.2", "domain": "d2", "prompt": "In a market analysis, Claude writes: 'A 2024 Gartner study found that 73% of mid-market firms adopted AI assistants.' The associate has never seen this study. What is the appropriate response to this level of specificity?", "options": ["Treat the specific citation as a checkable claim that could be fabricated, and verify the study exists and says this before using it.", "Round the number to 'about 70%' so the claim is safer to publish.", "Ask Claude to confirm the source, and keep the claim if it provides details.", "Treat the specificity as a credibility signal — invented numbers are rarely that precise."], "answer": 0, "why": "Hallucinated details are dangerous precisely because they are specific and fluent — specificity is not verification. Checkable specifics (named studies, percentages, section numbers) must be verified externally; softening the number or asking the model to confirm its own claim does not validate anything."}, {"id": "p7", "task": "2.4", "domain": "d2", "prompt": "An associate used Claude to draft revised liability wording for a customer contract. The draft looks excellent and the deal closes tomorrow, but Legal's review queue is a week long. What should the associate do?", "options": ["Remove the clause from the contract so no review is needed.", "Send the clause — it was refined over several careful iterations with Claude.", "Ask Claude to double-check the clause against common legal standards, then send.", "Get a qualified human review anyway (e.g., flag a one-clause expedited review or use pre-approved fallback language) — contract terms are a mandatory review category regardless of how good the draft looks."], "answer": 3, "why": "Binding, external, irreversible content — contracts, legal, regulated communications — requires qualified human review triggered by the CATEGORY, not by apparent quality. Iteration with the model is not review; model self-checks are not legal judgment; and deleting negotiated terms to dodge review harms the deal."}, {"id": "p8", "task": "2.5", "domain": "d2", "prompt": "A manager has a technical incident postmortem and must inform executives, customers, and engineers. While adapting the customer version, Claude adds 'no customer data was affected' — a claim the postmortem never addresses. What does this illustrate?", "options": ["Audience adaptation may change depth and framing but must never add claims the source doesn't support — unsourced additions get verified or removed.", "Technical content should not be adapted for non-technical audiences.", "Customer communications should always include reassurance, so the addition is appropriate.", "The three versions should be merged into one document to avoid inconsistencies."], "answer": 0, "why": "Adapting for an audience means translating the same facts, not inventing friendlier ones. Reassuring claims about data safety are exactly the kind of addition that must be verified with the source team or cut. One-size-fits-all documents and refusing adaptation both fail the audiences."}, {"id": "p9", "task": "2.6", "domain": "d2", "prompt": "A procurement analyst asks Claude to compare three vendors and receives four paragraphs of prose. The comparison will be imported into a tracking sheet and updated after each demo call. What should the analyst request?", "options": ["A criteria-by-vendor table plus a CSV version for the sheet, maintained as an artifact since it will be updated and shared.", "A separate chat for each vendor to keep the details organized.", "A shorter prose summary that is easier to skim.", "The same prose but with bold headings for each vendor."], "answer": 0, "why": "Format follows downstream use: comparison → table; import → structured data (CSV); updated-and-shared deliverable → artifact. Prose in any styling defeats comparison and import, and splitting vendors across chats makes comparison harder still."}, {"id": "p10", "task": "3.1", "domain": "d3", "prompt": "A marketing associate rebuilds the same setup in every chat — pasting the positioning doc, competitor list, and tone guide — and also needs each weekly update to reflect this week's competitor announcements. Which feature combination fits?", "options": ["Research mode alone, since current information is the priority.", "A saved mega-prompt containing all the context, pasted into each new chat.", "One continuous chat that accumulates all the context and all the weekly updates.", "A Project holding the durable context as instructions and knowledge, with research mode used in-Project for current announcements."], "answer": 3, "why": "Recurring context belongs in a Project (instructions + knowledge, set once); current sourced facts need research mode; the features compose. A pasted mega-prompt still repeats setup and drifts, an eternal chat hits context limits, and research mode alone re-loses the durable context weekly."}, {"id": "p11", "task": "3.2", "domain": "d3", "prompt": "A support team runs two jobs: drafting first-reply suggestions for ~2,000 routine, human-reviewed tickets per day, and a quarterly root-cause analysis of six months of escalation data for executives. How should models be assigned?", "options": ["A fast, economical model for the high-volume reviewed drafts; the most capable model for the complex quarterly analysis.", "The economical model for both, since the reviewed drafts prove it is adequate.", "The most capable model for both — support quality should never be compromised.", "A mid-tier model for both, as a compromise between the two needs."], "answer": 0, "why": "Model families trade capability against speed and cost. High-volume, well-defined, human-reviewed work fits the fast economical tier; low-volume, genuinely complex, high-stakes reasoning justifies the most capable tier. One-size assignments overpay on one job or underserve the other."}, {"id": "p12", "task": "3.4", "domain": "d3", "prompt": "After three weeks in one continuous chat, Claude drafts a counter-offer using the wrong walk-away price — a constraint set on day one. Quality has been degrading for days. What is the appropriate fix?", "options": ["Retype the walk-away price into the same chat, in capital letters, and continue.", "Scroll up and quote the original message so Claude can see it again.", "Report the model as faulty and switch tools for the negotiation.", "Summarize the durable decisions and constraints, persist them in Project instructions/knowledge, and continue the work in fresh chats."], "answer": 3, "why": "Long conversations exceed the effective context window: early details drop out and quality degrades. The structural fix is summarize-and-restart with durable context persisted in a Project. Re-typing into the overloaded chat treats the symptom, and the behavior is a context limitation, not a defect."}, {"id": "p13", "task": "4.1", "domain": "d4", "prompt": "Leadership sends a one-line request: 'We need an AI chatbot for HR.' What is the most valuable first use of Claude?", "options": ["Build a prototype in a Project so stakeholders have something concrete to react to.", "Draft the full project plan immediately so leadership sees fast progress.", "Use Claude to surface the unanswered requirements — users, top tasks, governance boundaries, success metrics — and draft acceptance criteria to validate with the requesters.", "Research which chatbot vendor has the best reviews."], "answer": 2, "why": "A plan built on a one-line requirement encodes guesses as commitments. Claude's highest-leverage first use is requirements analysis: surfacing unknowns, stakeholders, constraints, and testable acceptance criteria for humans to confirm. Plans, vendors, and prototypes all come after the problem is defined."}, {"id": "p14", "task": "4.2", "domain": "d4", "prompt": "An ops lead gives Claude the documented 14-step onboarding process and asks for bottleneck analysis. Claude proposes re-ordering steps 4–6, projecting five days saved. What should happen before the change is adopted?", "options": ["Adopt it — the analysis was based on the official process documentation.", "Validate the proposal with the people who run those steps, since the documented process may omit real dependencies the model cannot see.", "Pilot the change secretly to avoid biasing the team's feedback.", "Ask Claude to redo the analysis with a more capable model to be sure."], "answer": 1, "why": "Claude reasons from the documented process; reality often contains undocumented dependencies (systems, policies, sequencing constraints). Process recommendations are hypotheses until validated with the people who operate the process. Re-running with a bigger model re-derives the same blind spot."}, {"id": "p15", "task": "4.3", "domain": "d4", "prompt": "A customer success manager asks Claude to fix a slow QBR-prep process. What engagement pattern best fits solution design work?", "options": ["Ask for multiple approaches with trade-offs against stated criteria, select one, pilot it with a few CSMs, and iterate the design on pilot feedback.", "Ask for the single best solution and implement it across all 40 CSMs.", "Ask Claude to fully automate the process end-to-end so design is unnecessary.", "Collect solutions from other companies and pick the most common one."], "answer": 0, "why": "Solution design is an arc — options with trade-offs, selection against criteria, pilot, iteration on evidence. Implementing a first suggestion org-wide skips the learning loop; full automation often violates constraints and exceeds an associate's remit; copying others ignores your criteria."}, {"id": "p16", "task": "4.4", "domain": "d4", "prompt": "A recruiting lead wants Claude in the hiring pipeline. Which placement follows sound workflow-integration principles?", "options": ["Claude conducts the initial screening calls via chat to save recruiter time.", "Claude ranks all 200 applicants per role so recruiters only interview the top ten.", "Keep AI out of recruiting entirely, since hiring affects people.", "Claude structures CV facts against the posted requirements and drafts summaries, while recruiters review every rejection and humans make all hiring decisions."], "answer": 3, "why": "Sound integration augments drudgery (extraction, structuring, drafting) and keeps judgment and accountability human — especially in a bias-sensitive, often regulated domain. Producing the ranking IS the hiring judgment; automating candidate conversations removes the human where it matters; and a blanket ban forfeits safe value."}, {"id": "p17", "task": "4.5", "domain": "d4", "prompt": "After a successful contract-review pilot (64% prep-time reduction) with one caught fabrication incident, an associate must brief executives — including an AI skeptic. What is the strongest communication approach?", "options": ["Present measured value with evidence AND the fabrication incident with the safeguard that caught it, framing limitations as operating rules.", "Focus on the underlying technology so executives understand how the model works.", "Lead with the time savings and omit the fabrication incident to keep the expansion on track.", "Let the skeptic present the risks while you present the benefits."], "answer": 0, "why": "Credible stakeholder communication pairs every value claim with evidence and every limitation with its mitigation — the caught failure demonstrates the safeguards work, which is what a skeptic needs to see. Omitting incidents destroys trust when they surface; technical deep-dives answer a question executives didn't ask."}, {"id": "p18", "task": "5.1", "domain": "d5", "prompt": "A content team pastes the same role, tone rules, product facts, and exemplar posts into every new chat, and drafts drift as teammates paste older versions. What is the right fix?", "options": ["Configure a Project: durable rules as instructions, reference documents as knowledge, so every chat starts briefed and consistent.", "Write a longer, more detailed prompt template for each content type.", "Use one shared team chat so the context only has to be pasted once.", "Maintain the setup text in a shared doc that everyone pastes from."], "answer": 0, "why": "Recurring context is what Projects exist for: instructions define how to work, knowledge defines what to know, and every new chat inherits both — current version, whole team. Shared paste-docs still drift and repeat; a communal mega-chat hits context limits; longer templates are the same ritual, longer."}, {"id": "p19", "task": "5.2", "domain": "d5", "prompt": "A sales Project answers pricing questions from an uploaded price list. Prices changed three weeks ago and reps are quoting stale numbers. Prices change monthly. What is the best correction?", "options": ["Replace the upload with a connector scoped to the folder where the live price sheet is maintained, and delete the stale upload.", "Add an instruction telling Claude to always use the latest prices.", "Re-upload the current price list and consider the issue resolved.", "Tell reps to verify all prices manually, since AI data cannot be trusted."], "answer": 0, "why": "Uploads are point-in-time snapshots; monthly-changing sources belong behind a connector that reads current content — scoped to the needed folder, with the stale snapshot removed so it can't silently win. An instruction cannot conjure data the Project doesn't have, and a one-time re-upload recreates the same failure next month."}, {"id": "p20", "task": "5.3", "domain": "d5", "prompt": "A support Project's instructions read: 'Be professional, accurate and concise. Try to be consistent with our policies.' Answers vary wildly and once included an invented refund exception. What makes replacement instructions effective?", "options": ["Specific, testable rules: answer only from Project policy documents, cite the document and section for every answer, escalate named categories, and say 'not covered' rather than infer.", "Adding more adjectives: 'be extremely accurate, very consistent, and highly professional.'", "A much longer document covering every situation agents might encounter.", "Removing instructions entirely and trusting the model's defaults."], "answer": 0, "why": "Instructions work when a stranger could check compliance: answer-only-from-knowledge makes invented policy impossible to deliver silently, citations make accuracy inspectable, and named escalation categories bound the risk. Adjectives aren't rules, and sprawl creates conflicts rather than control."}, {"id": "p21", "task": "5.4", "domain": "d5", "prompt": "A Project configured excellently in March is confidently giving September users outdated warranty terms, obsolete contacts, and superseded section references. What does this situation call for?", "options": ["A maintenance system: a named owner, event-triggered updates when policies change, a periodic sweep of knowledge and instructions, and visible versioning.", "Recreating the Project from scratch each quarter to guarantee freshness.", "A more capable model that is better at recognizing outdated information.", "An instruction telling Claude to warn users its knowledge may be outdated."], "answer": 0, "why": "Configuration is a living system — knowledge staleness is an ownership and process failure, not a model failure. Owners, update triggers, review cadence, and versioning keep the Project true. No model can detect that a policy changed outside its knowledge, blanket warnings train users to ignore them, and quarterly rebuilds lose accumulated refinement."}, {"id": "p22", "task": "6.1", "domain": "d6", "prompt": "A team proposes letting Claude automatically respond to and settle inbound insurance claims under $500 to match competitors' payout speed. How should an associate assess this use case?", "options": ["Reject AI involvement in claims entirely.", "Approve it with a disclaimer to claimants that AI processed their claim.", "Refactor it: Claude triages, checks coverage, and drafts the disposition in seconds, but a licensed adjuster approves each decision — autonomous binding decisions about people's money are not an appropriate AI use case.", "Approve it — small claims are low-stakes and the volume savings are large."], "answer": 2, "why": "Fit is judged on stakes, reversibility, and accountability — binding financial decisions affecting people, unreviewed before impact and likely subject to automated-decision rules, fail that screen. The refactor keeps the speed value while a human accountably decides. Blanket rejection forfeits safe value; a disclaimer doesn't create review."}, {"id": "p23", "task": "6.3", "domain": "d6", "prompt": "Company policy requires senior-manager review of AI-assisted client deliverables. The designated reviewer is on leave and the deadline is this week. The draft is excellent. What should the associate do?", "options": ["Deliver with a note that review will follow retroactively once the manager returns.", "Deliver without mentioning the AI assistance — the associate reviewed it personally and quality is high.", "Find a compliant path (covering reviewer, deadline extension, or non-AI preparation), then raise the single-reviewer gap with the policy owner.", "Use a personal AI account instead, since the policy covers company tools."], "answer": 2, "why": "Policies bind even when inconvenient; the professional move is comply-then-escalate — solve delivery within the rules and fix the policy gap through governance. Hiding AI involvement is a violation with a long tail, retroactive review isn't review, and personal-account workarounds are shadow AI, the worst of the options."}, {"id": "p24", "task": "6.4", "domain": "d6", "prompt": "A credit-card campaign segmentation built from historical approval patterns almost entirely excludes two historically underbanked zip-code clusters. What is the appropriate response?", "options": ["Launch anyway — the model only reflects real historical data.", "Launch with a disclosure that segmentation was AI-assisted.", "Halt the launch, rebuild the segmentation on forward-looking behavioral criteria, involve compliance, and document the finding.", "Add the excluded zip codes back manually and launch."], "answer": 2, "why": "A model trained on skewed history reproduces the skew with confidence — this pattern can be both unethical and, in credit contexts, unlawful. The response is to stop, rebuild on legitimate criteria, engage compliance, and document. 'The data is the data' launders past bias; manual patching hides the mechanism; disclosure doesn't repair discrimination."}, {"id": "p25", "task": "7.1", "domain": "d7", "prompt": "A weekly KPI-commentary prompt that worked for months now invents targets and discusses metrics absent from the attached export. What is the correct troubleshooting approach?", "options": ["Classify the failure first — here, fabrication filling a context gap (likely a changed export format) — apply a targeted fix, and re-test on the same input.", "Switch to a different model, since this one has started hallucinating.", "Add 'be more accurate, do not hallucinate' to the prompt and continue.", "Re-run the prompt a few times and use the best output each week."], "answer": 0, "why": "Sudden fabrication after months of success points to a changed input, not a changed model — the missing target data left a gap that plausible inventions filled. Diagnosis before remedy: classify the failure type, fix that cause, verify on the same input. Accuracy exhortations, re-rolls, and model swaps are all guesses that skip the diagnosis."}, {"id": "p26", "task": "7.2", "domain": "d7", "prompt": "Six weeks of feedback on an AI proposal workflow: pricing sections heavily edited in 9 of 12 proposals; two reps call the tone too formal for startups; one VP called one proposal 'unusable' with no specifics; exec summaries are praised. How should the team act?", "options": ["Prioritize by pattern strength: diagnose the systematic pricing edits first, apply the cheap tone fix, log the unspecific anecdote for follow-up, and change nothing about the praised summaries.", "Address all four signals at once so every stakeholder sees a response.", "Add a disclaimer that drafts may require editing.", "Rebuild the workflow — a VP calling output unusable is a serious signal."], "answer": 0, "why": "Feedback is triaged by frequency and impact, not seniority or volume: a 75% systematic edit-rate outranks an n=1 anecdote. Diagnose the pattern, fix one lever at a time, re-measure, and explicitly protect what works. Rebuilds for anecdotes and simultaneous changes destroy the ability to learn what fixed what."}, {"id": "p27", "task": "7.3", "domain": "d7", "prompt": "A working localization flow is heavy: context re-pasted into every chat, five sequential regional chats per item, and one bilingual reviewer reading everything — a two-day bottleneck. Which optimization keeps quality while cutting cost?", "options": ["Move durable context into a Project, batch the five regional variants into one structured pass, right-size the model to the task, and refocus the reviewer on AI-flagged risky choices with spot-checks for the rest.", "Upgrade every step to the most capable model so review becomes unnecessary.", "Ask the reviewer to work faster and set a same-day review SLA.", "Remove the human review step, since the outputs have been reliable."], "answer": 0, "why": "Optimization removes redundancy — repeated context, sequential near-duplicate work, over-provisioned models — while keeping the quality safeguard and aiming it where risk concentrates. Deleting review removes the safety net, maximal models don't eliminate the need for review, and pressuring the bottleneck human changes nothing structural."}];
  const cheat = [{"d": "d1", "fact": "Effective prompt = context + role/audience + task + constraints + output format. The best exam option adds specifics — never just 'be more detailed'.", "task": "1.1"}, {"d": "d1", "fact": "Complex deliverables: decompose into sequenced steps WITH human review between them — beats both one mega-prompt and blind prompt-chaining.", "task": "1.2"}, {"d": "d1", "fact": "Iterate with anchored, directional feedback (keep X, change Y, because Z). 'Make it better' regenerates the good parts away.", "task": "1.3"}, {"d": "d1", "fact": "Match prompt shape to task type: brainstorm = many unfiltered ideas, judgment deferred; analysis = explicit criteria + structure; research = scope + sources; drafting = audience + tone + format.", "task": "1.4"}, {"d": "d2", "fact": "Evaluate every output on TWO axes: accuracy (check present claims against the source) and completeness (check coverage against the request — omissions hide).", "task": "2.1"}, {"d": "d2", "fact": "Specificity is not credibility: confident citations, statistics, and section numbers are exactly what hallucinations look like.", "task": "2.2"}, {"d": "d2", "fact": "Self-reported confidence is NEVER a validation signal. Verify against an authoritative external source — the official sample answer.", "task": "2.3"}, {"d": "d2", "fact": "Match validation to claim type: citation → open the source; statistic → recompute/trace; legal-regulated → official text + expert. Effort scales with stakes.", "task": "2.3"}, {"d": "d2", "fact": "Mandatory human review is triggered by CATEGORY (legal, medical, financial, HR, external, contractual, irreversible), not by how good the output looks.", "task": "2.4"}, {"d": "d2", "fact": "Iterating with Claude ≠ review. Ten refinement rounds is still zero qualified human eyes.", "task": "2.4"}, {"d": "d2", "fact": "Audience adaptation changes depth and framing but must never ADD claims the source doesn't support.", "task": "2.5"}, {"d": "d2", "fact": "Format follows downstream use: updated/shared → artifact; imported/analyzed → structured data (table/CSV); quick answer → inline.", "task": "2.6"}, {"d": "d3", "fact": "Feature cues: recurring context → Project; current/cited info → research mode; shareable evolving deliverable → artifact; one-off → chat. Features compose.", "task": "3.1"}, {"d": "d3", "fact": "Haiku = fastest/most economical (high-volume, well-defined); Sonnet = balanced everyday default; Opus = most capable (complex reasoning, highest cost/latency).", "task": "3.2"}, {"d": "d3", "fact": "Official sample: high-volume, speed/cost-sensitive replies → faster, lower-cost model. 'Most capable everywhere' is always the distractor.", "task": "3.3"}, {"d": "d3", "fact": "Requirements first, then the cheapest model that clears the bar; a human review step lowers the model-quality floor a task needs.", "task": "3.3"}, {"d": "d3", "fact": "Long chat degrading / early instructions lost = context limit, not model fault: summarize + fresh chat; durable context → Project instructions/knowledge.", "task": "3.4"}, {"d": "d4", "fact": "Vague request? Analysis before artifact: surface requirements, stakeholders, constraints, and acceptance criteria — then produce.", "task": "4.1"}, {"d": "d4", "fact": "Claude's process recommendations are hypotheses — validate with the people who run the process before adopting.", "task": "4.2"}, {"d": "d4", "fact": "Solution design arc: options with trade-offs → select by criteria → pilot → iterate on evidence. Never first-suggestion-to-production.", "task": "4.3"}, {"d": "d4", "fact": "Integrate AI at drudgery steps (draft, summarize, classify, structure); humans keep judgment steps (approve, decide, hire, settle) and quality gates.", "task": "4.4"}, {"d": "d4", "fact": "Stakeholder credibility = measured value WITH evidence + named limitations WITH mitigations. Tell the failure story yourself.", "task": "4.5"}, {"d": "d5", "fact": "Projects: instructions = HOW to work (stable rules); knowledge = WHAT to know (reference docs). Team repeats context every chat → configure a Project.", "task": "5.1"}, {"d": "d5", "fact": "Uploads are frozen snapshots; connectors (Drive, Gmail) read current content. Changes weekly → connector, scoped to the needed folder; delete stale uploads.", "task": "5.2"}, {"d": "d5", "fact": "Good instructions are specific and testable: 'answer only from Project docs, cite doc + section, escalate named categories'. Adjectives are not rules.", "task": "5.3"}, {"d": "d5", "fact": "Stale-Project symptoms need a maintenance system: named owner, event-triggered updates, periodic sweep, visible versioning — not a bigger model.", "task": "5.4"}, {"d": "d6", "fact": "Use-case screen: What if it's wrong? Who reviews before impact? Is the data allowed? Who is accountable? AI assists judgment; it doesn't replace it.", "task": "6.1"}, {"d": "d6", "fact": "Official sample: regulated identifiers → remove/anonymize BEFORE upload, per policy. 'It's internal', 'tell it not to retain', and 'skip the task' are the distractors.", "task": "6.2"}, {"d": "d6", "fact": "Minimize by default: share only the fields the task needs; the analysis usually survives anonymization intact.", "task": "6.2"}, {"d": "d6", "fact": "Policy inconvenient? Comply-then-escalate through governance. Undefined ≠ approved; personal-account workarounds = shadow AI.", "task": "6.3"}, {"d": "d6", "fact": "Ethics beyond policy: check outputs across groups for bias, disclose AI involvement where it matters, keep a named human accountable for every consequential output.", "task": "6.4"}, {"d": "d7", "fact": "Diagnose before fixing: wrong facts → context/knowledge gap; wrong focus → ambiguity; wrong shape → format unstated; ignores rules in long chat → context overflow. Change ONE variable, re-test same input.", "task": "7.1"}, {"d": "d7", "fact": "'Worked for months, now fails' → an INPUT changed (export format, stale doc), not the model. Find what changed.", "task": "7.1"}, {"d": "d7", "fact": "Triage feedback by frequency × impact: systematic edit-patterns outrank loud n=1 anecdotes; explicitly protect what already works.", "task": "7.2"}, {"d": "d7", "fact": "Optimize by removing redundancy (Project context, batching, right-sized models, review focused on flagged risk) — with the quality metric visible BEFORE the change. Never optimize away the safety net.", "task": "7.3"}];
  const mock = [{"id": "m1", "task": "1.1", "domain": "d1", "prompt": "An associate needs Claude to draft a message announcing a delayed product release to enterprise customers. Which prompt is most likely to produce a usable draft on the first attempt?", "options": ["\"Write an announcement about the product delay for our enterprise customers — make it sincere, on-brand, and not too corporate.\"", "\"Write a very professional, high-quality, detailed announcement about the product delay. Tone and accuracy matter enormously, so make it excellent.\"", "\"You are the world's best crisis communications expert with 30 years at Fortune 100 companies. Write our product delay announcement.\"", "\"Draft a 150-word candid email to enterprise customers: Q3 release moves to November, the reason, impact on commitments, a named contact.\""], "answer": 3, "why": "The strong prompt supplies audience, length, tone, and the required content elements — the actual requirements. Quality adjectives and grand persona labels add no requirements, so both leave the model guessing at the same unknowns as the bare request.", "ref": "D1 Prompting and Task Execution — Lesson 1.1"}, {"id": "m2", "task": "1.1", "domain": "d1", "prompt": "A finance associate keeps getting Claude outputs in flowing prose when they need content they can drop into a slide. What element is their prompt most likely missing?", "options": ["Longer background about the company, so the model can judge what belongs on the slide.", "An explicit output-format specification — for example, '5 bullets, max 12 words each.'", "A more capable model tier, since slide-ready business content demands stronger reasoning.", "A politeness marker: models are trained on human dialogue and respond better to courteous phrasing."], "answer": 1, "why": "Output shape is a prompt element like any other: if the format isn't stated, the model defaults to prose. Courtesy, model tier, and extra background don't communicate the missing requirement — the format specification does.", "ref": "D1 Prompting and Task Execution — Lesson 1.1"}, {"id": "m3", "task": "1.2", "domain": "d1", "prompt": "A consultant must produce a 40-page client readiness assessment. Asking Claude for the whole document at once yields shallow, partly inconsistent content. What is the best restructuring of the work?", "options": ["Decompose it: outline first, then each section drafted in sequence, reviewed before the next builds on it.", "Generate the full document five times and merge the strongest chapters from the different runs.", "Split it across five parallel chats, one per section, with the same brief in each, and staple the results together.", "Ask for the whole document again, adding 'be thorough and keep it internally consistent throughout.'"], "answer": 0, "why": "Sequenced decomposition with review between steps keeps each unit verifiable and lets corrected output ground the next step. Merging independent generations and parallel unreviewed chats both reproduce the inconsistency problem; exhortations to be thorough change nothing structural.", "ref": "D1 Prompting and Task Execution — Lesson 1.2"}, {"id": "m4", "task": "1.2", "domain": "d1", "prompt": "While decomposing a complex analysis into steps, an associate wonders when to pause for their own review of Claude's output. What is the guiding principle?", "options": ["Review only the final combined deliverable, to preserve momentum.", "Review at random intervals, so the checking stays unbiased.", "Review is unnecessary if each step's prompt was well-written.", "Review after every step whose output feeds the next step."], "answer": 3, "why": "The value of decomposition comes from checkpoints: an unverified early output poisons everything built on it. Final-only review discovers compounded errors at the most expensive moment; good prompts reduce but never remove the need to verify.", "ref": "D1 Prompting and Task Execution — Lesson 1.2"}, {"id": "m5", "task": "1.3", "domain": "d1", "prompt": "Claude's draft of a client FAQ has strong answers but the wrong reading level and several missing topics. Which follow-up gets the best next iteration?", "options": ["\"Make it simpler and more complete — the reading level is too high and several topics are still missing entirely.\"", "\"This isn't right — try again. I need something a lot closer to what our customers actually ask us about.\"", "\"Keep the ten answers. Rewrite at an 8th-grade level; add billing, cancellation, and data-export entries from the policy.\"", "Start a fresh chat with a much longer, more detailed opening prompt and regenerate all ten answers from scratch."], "answer": 2, "why": "Anchored feedback preserves what works, names the specific changes, and supplies the missing inputs for the gaps. Undirected retries and vague comparatives regenerate at random; restarting discards ten good answers the iteration should have kept.", "ref": "D1 Prompting and Task Execution — Lesson 1.3"}, {"id": "m6", "task": "1.3", "domain": "d1", "prompt": "After three feedback rounds, Claude still can't produce the right competitive positioning section — each revision guesses differently at the competitor's pricing. What does this convergence failure signal?", "options": ["The model has hit its capability ceiling here; a more capable tier is the only remaining fix.", "The feedback wording is too gentle; firmer, more directive phrasing will force convergence.", "The prompt is missing information the model cannot invent — supply the competitor's pricing data.", "The conversation belongs in a Project, whose instructions would keep the revisions consistent."], "answer": 2, "why": "When iterations keep guessing at the same detail, the gap is missing input, not phrasing: no amount of feedback conjures facts the model was never given. Capability, forcefulness, and Project structure don't address an information deficit.", "ref": "D1 Prompting and Task Execution — Lesson 1.3"}, {"id": "m7", "task": "1.4", "domain": "d1", "prompt": "A strategy associate has four tasks: score three vendors against criteria, gather current market entrants, write a board memo, and generate campaign concepts. Which pairing of task and prompting strategy is correct?", "options": ["All four in one combined prompt, so that the four outputs stay consistent with each other.", "Board memo → maximum idea quantity; market entrants → a single polished narrative written from memory.", "Vendor scoring → a large batch of unfiltered creative options; campaign concepts → one polished recommendation.", "Campaign concepts → many diverse, unjudged ideas; vendor scoring → explicit criteria and a structured table."], "answer": 3, "why": "Brainstorming rewards divergence (quantity, variety, deferred judgment) while analysis rewards convergence (criteria, structure). Crossing the modes — creative breadth for scoring, single answers for ideation — or fusing all four tasks produces the wrong shape for every task.", "ref": "D1 Prompting and Task Execution — Lesson 1.4"}, {"id": "m8", "task": "1.4", "domain": "d1", "prompt": "An associate researching new privacy legislation for a briefing asks Claude to 'brainstorm what the law probably says.' What is wrong with this approach?", "options": ["Nothing — brainstorming surfaces more possibilities than a narrow, direct question would.", "Legislation is a regulated topic, so drafting anything about it with an AI tool is prohibited.", "The prompt should have asked for more ideas, since coverage improves with the number generated.", "Research tasks need real sources and verification; ideation prompts invite plausible invention."], "answer": 3, "why": "Task type dictates strategy: legal content is a research task with verifiable ground truth, so the prompt should demand sources and scope, not creative speculation. Brainstorming what facts 'probably' are is a recipe for confident fabrication.", "ref": "D1 Prompting and Task Execution — Lesson 1.4"}, {"id": "m9", "task": "2.1", "domain": "d2", "prompt": "Claude summarizes a 40-page vendor contract for an associate. The summary reads smoothly and matches everything the associate remembers about the deal. Before the summary informs a renewal decision, what evaluation is required?", "options": ["Check key terms and dates against the contract, and confirm it covers the sections the decision needs.", "Ask Claude to re-read the contract and confirm its own summary is accurate and complete.", "None needed — it matches the associate's own recollection of how the deal was negotiated.", "Compare its length and structure against summaries of similar vendor contracts from last year."], "answer": 0, "why": "Memory and fluency are weak evaluators; decisions need claims verified against the source and coverage checked against the decision's needs — omitted clauses are as dangerous as wrong ones. A model confirming itself re-runs the same process that made any error.", "ref": "D2 Output Evaluation and Validation — Lesson 2.1"}, {"id": "m10", "task": "2.1", "domain": "d2", "prompt": "An associate asked Claude for 'the risks in this supplier proposal' and received six well-explained risks. The most reliable way to catch what the response MISSED is to:", "options": ["Check whether six risks is a typical number for supplier proposals of this size and complexity.", "Check that each of the six risks is well-reasoned and clearly explained in the response.", "Re-read the proposal, checking each section for risks the six items miss.", "Ask Claude whether its list is complete and whether it left anything material out."], "answer": 2, "why": "Completeness failures are invisible from inside the output — they're found by comparing the output against the source material. Verifying only what's present checks accuracy, not coverage, and self-reported completeness is no more reliable than self-reported confidence.", "ref": "D2 Output Evaluation and Validation — Lesson 2.1"}, {"id": "m11", "task": "2.2", "domain": "d2", "prompt": "A Claude-drafted industry overview cites 'the 2025 McKinsey Logistics Outlook, p. 47' for a key statistic. The associate cannot find this report anywhere. What has most likely happened?", "options": ["The model fabricated a plausible citation; the statistic needs a real source.", "The report is probably paywalled or client-only, so the citation can stand and the statistic holds.", "The page number is slightly wrong, but the statistic itself is still trustworthy.", "The model drew on a licensed database that the associate's account cannot reach."], "answer": 0, "why": "Invented citations with realistic titles and page numbers are a classic hallucination: the model produces the FORM of evidence without the substance. An unverifiable citation cannot support a claim — assuming paywalls, secret access, or minor errata extends trust the output hasn't earned.", "ref": "D2 Output Evaluation and Validation — Lesson 2.2"}, {"id": "m12", "task": "2.2", "domain": "d2", "prompt": "Halfway through a long Claude-generated report, the projected savings figure changes from $2.1M to $1.6M with no explanation. What kind of defect is this, and what does it require?", "options": ["Expected behavior in long outputs, where figures drift over length; no action is needed here.", "A hallucinated citation — remove both figures and the surrounding paragraph.", "An internal inconsistency: trace both figures to the source data before the report is used.", "A rounding or presentation convention — pick whichever figure reads better and use it throughout."], "answer": 2, "why": "Contradictory figures within one output are an inconsistency defect: at least one number is wrong, and only reconciliation against the source data reveals which. Picking one arbitrarily or normalizing the defect ships a 24% error either way.", "ref": "D2 Output Evaluation and Validation — Lesson 2.2"}, {"id": "m13", "task": "2.2", "domain": "d2", "prompt": "Claude drafts interview screening criteria from a team's 'best performer profiles' and the criteria heavily favor traits of the current team's demographic majority. What should the associate recognize?", "options": ["Adding more of the team's best-performer profiles to the sample will balance the criteria out.", "The output may encode bias from a skewed sample; check it against the job spec.", "The model is malfunctioning and the behavior should be reported to the vendor's support.", "The criteria are objective, since they were derived from the team's real performance data."], "answer": 1, "why": "Bias in outputs often arrives via bias in inputs: a homogeneous 'best performer' sample teaches demographic echo, not job competence. Recognizing systematic skew and re-grounding criteria in validated requirements is the evaluation skill; more of the same data deepens the skew.", "ref": "D2 Output Evaluation and Validation — Lesson 2.2"}, {"id": "m14", "task": "2.3", "domain": "d2", "prompt": "Claude produces a competitive brief containing: (a) a competitor's claimed new feature, (b) a computed market-share percentage, and (c) a quoted line from a CEO interview. Which validation mapping is correct?", "options": ["(a) the competitor's press release; (b) recompute the figure; (c) find the original interview.", "All three: ask Claude to double-check its own work before the brief circulates.", "(a) and (c) need no validation; (b) should be rounded to a safe range before publication.", "All three: accept any claim that at least two other AI assistants independently agree with."], "answer": 0, "why": "Validation technique follows claim type: product claims trace to the company's own announcements, computed statistics get recomputed, quotes get located in the primary source. Self-checks re-run the same model, agreement between AI tools isn't ground truth, and rounding doesn't validate anything.", "ref": "D2 Output Evaluation and Validation — Lesson 2.3"}, {"id": "m15", "task": "2.3", "domain": "d2", "prompt": "An associate has 20 Claude-generated claims to validate before a deadline and cannot deep-verify all of them. How should validation effort be allocated?", "options": ["Give every claim equal time, so the validation effort stays consistent and defensible in an audit.", "Fully validate the ten easiest claims and flag the remaining ten as unverified.", "By stakes: deep-verify what the decision rests on, spot-check the low-consequence rest.", "Skip validation this once and add a general disclaimer about AI-assisted content to the deck."], "answer": 2, "why": "Validation depth scales with the cost of being wrong. Stakes-based triage puts scarce effort where errors do damage; uniform effort over-checks trivia while under-checking the material claims, ease-based selection inverts the priority, and disclaimers don't validate.", "ref": "D2 Output Evaluation and Validation — Lesson 2.3"}, {"id": "m16", "task": "2.3", "domain": "d2", "prompt": "To validate a Claude-drafted summary of a new tax rule, an associate asks Claude 'Are you sure this is correct?' and receives 'Yes — this reflects the current rule.' What has the associate learned?", "options": ["The summary is validated: the model checked its own work and confirmed it is correct.", "The summary is probably wrong, since an honest model expresses doubt when challenged.", "The summary is now more likely correct, since a wrong answer wouldn't survive a challenge.", "Essentially nothing — models reaffirm their own errors; the rule text is the check."], "answer": 3, "why": "Asking the generator to grade itself re-samples the process that produced any error — confident reaffirmation is common and carries no evidential weight in either direction. External authoritative verification is the only move that adds information.", "ref": "D2 Output Evaluation and Validation — Lesson 2.3"}, {"id": "m17", "task": "2.4", "domain": "d2", "prompt": "Which of these Claude outputs can an associate reasonably use after self-review alone, without routing to a qualified human reviewer?", "options": ["Dosage-related wording for the user leaflet of a home medical device.", "A written explanation of severance terms to be sent to a departing employee this week.", "A first-draft agenda and notes for the team's internal weekly sync.", "A public statement responding to a customer's rumor about a data breach at the company."], "answer": 2, "why": "Review triggers are categorical: personnel/legal terms, public crisis statements, and medical content all carry consequences that mandate qualified review regardless of draft quality. A routine internal agenda is low-stakes and reversible — self-review suffices.", "ref": "D2 Output Evaluation and Validation — Lesson 2.4"}, {"id": "m18", "task": "2.4", "domain": "d2", "prompt": "A team routes every single Claude output — including routine internal drafts — to the legal team 'to be safe.' Legal now rubber-stamps the queue. What has the team gotten wrong about human review?", "options": ["Review must track risk: flooding reviewers with trivia degrades scrutiny.", "Legal review should be replaced by a second model reviewing the first model's output.", "Nothing is wrong — routing every output through legal is the maximally safe posture.", "Reviews should be sampled at random, 10% of outputs, regardless of what they contain."], "answer": 0, "why": "Indiscriminate review is a failure mode, not a safety posture: reviewer attention is finite, and rubber-stamping means high-stakes items get the same glance as trivia. Categorical triggers concentrate qualified eyes where consequences live. AI-reviewing-AI and blind sampling both miss the point of qualified judgment.", "ref": "D2 Output Evaluation and Validation — Lesson 2.4"}, {"id": "m19", "task": "2.5", "domain": "d2", "prompt": "An associate must deliver quarterly results to the board and to the engineering all-hands. Claude produced one competent document. What is the right next step?", "options": ["Send the same document to both audiences — the underlying facts don't change with the reader.", "Send the board a shortened copy with the technical paragraphs deleted from the middle.", "Send engineering the board version with a glossary of the business terms appended.", "Generate two variants: decisions and impact for the board, specifics for engineering."], "answer": 3, "why": "Adaptation is translation for what each audience must do with the information, not truncation. Deleting paragraphs loses content the board needs framed differently (not removed), and glossaries patch vocabulary while leaving the wrong emphasis. One-document-fits-all serves neither audience.", "ref": "D2 Output Evaluation and Validation — Lesson 2.5"}, {"id": "m20", "task": "2.6", "domain": "d2", "prompt": "A team lead asks Claude for a quick definition of 'net revenue retention' during a chat, and separately for a 30-criteria security-questionnaire response matrix that three teams will fill in over two weeks. Which format pairing is right?", "options": ["Both as artifacts, since artifacts are more professional and easier to share.", "Definition → an inline chat answer; matrix → a structured artifact the teams update.", "Definition → a table for precision; matrix → prose so it reads more naturally.", "Both inline in chat, so the whole thread stays in one searchable place for everyone."], "answer": 1, "why": "Downstream use picks the format: a conversational fact needs an inline sentence; a multi-team, multi-week, updated deliverable needs a structured, durable artifact. Over-formatting trivia and under-formatting working documents are the twin failures.", "ref": "D2 Output Evaluation and Validation — Lesson 2.6"}, {"id": "m21", "task": "2.6", "domain": "d2", "prompt": "Claude returns a 25-item risk assessment as one undifferentiated wall of prose. The audience needs to act on it in a review meeting. What curation should the associate request?", "options": ["Group by category, rank by severity, put the top five in a table, appendix the rest.", "None — the content is complete, and the meeting can work through the prose together.", "Convert every one of the 25 items into its own small table, for consistency.", "Cut the assessment down to the five most severe items so that it fits on a single slide."], "answer": 0, "why": "Curation — grouping, ranking, surfacing the actionable few while preserving the rest — is what turns complete information into usable information. Deleting 20 items discards the record; 25 one-row tables is formatting noise; raw prose forces the meeting to do the organizing.", "ref": "D2 Output Evaluation and Validation — Lesson 2.6"}, {"id": "m22", "task": "3.1", "domain": "d3", "prompt": "A consultant answers client questions all day using the same methodology decks and templates, and today also needs current statistics on a fast-moving regulation. Which product-feature setup fits?", "options": ["Research mode for every question, since it is the most capable feature available to the team.", "A Project holding the decks and templates, with research mode used in it for current facts.", "An artifact containing the methodology content, pasted as a reference into each new chat.", "A plain chat, with the methodology decks re-uploaded whenever they seem relevant to a question."], "answer": 1, "why": "Durable recurring context belongs in Project knowledge and instructions; live sourced facts are research mode's job; the two compose in the same chat. Research mode doesn't hold your methodology, re-uploading is the ritual Projects remove, and artifacts are deliverables, not context stores.", "ref": "D3 Product and Model Selection — Lesson 3.1"}, {"id": "m23", "task": "3.1", "domain": "d3", "prompt": "An associate asks plain chat (without research mode) for 'this quarter's funding rounds in our industry' and gets a detailed, dated list. How should they treat this output?", "options": ["As current — the entries carry specific dates, amounts, and named investors.", "As current, provided the chat was started today and the question explicitly named this quarter.", "As reliable, once the model has confirmed the list is up to date when asked.", "As unreliable for recency: training data has a cutoff — use research mode."], "answer": 3, "why": "A model without live research answers recency questions from training data and may present stale or invented specifics with full confidence — today's date on the chat doesn't update the knowledge, and self-confirmation adds nothing. Current-events tasks need the feature built for them.", "ref": "D3 Product and Model Selection — Lesson 3.1"}, {"id": "m24", "task": "3.2", "domain": "d3", "prompt": "Which task assignment correctly matches Claude model tiers to workloads?", "options": ["Haiku for tagging 10,000 tickets; Sonnet for report drafting; Opus for the legal analysis.", "Opus for all three, to standardize the team on one model and simplify support and billing.", "Haiku for the nuanced multi-document legal risk analysis; Opus for tagging the 10,000 tickets.", "Sonnet for all three, since it balances capability, cost, and latency for any workload."], "answer": 0, "why": "Capability should follow task complexity: high-volume classification fits the fast economical tier, everyday drafting fits the balanced tier, and deep cross-document reasoning justifies the most capable tier. Inverting the mapping overpays on volume and underserves complexity; single-model standardization does one or the other everywhere.", "ref": "D3 Product and Model Selection — Lesson 3.2"}, {"id": "m25", "task": "3.2", "domain": "d3", "prompt": "A colleague argues: 'Model choice is irrelevant now — just always pick the most capable one; compute is cheap.' For a 50,000-call/month automated workflow, what is the strongest counterpoint?", "options": ["At 50,000 calls a month, per-call cost and latency multiply with no matching quality gain.", "The most capable model should be reserved for executive and customer-facing work only.", "More capable models are measurably less accurate on simple classification work.", "There is no counterpoint; maximum capability is always the safe default at any volume."], "answer": 0, "why": "The trade-off is real at scale: cost and latency are per-call taxes multiplied 50,000 times monthly, while marginal quality often disappears behind existing review nets on straightforward tasks. The counterargument is economic fit, not a claim that capable models perform worse or belong to a status hierarchy.", "ref": "D3 Product and Model Selection — Lesson 3.2"}, {"id": "m26", "task": "3.3", "domain": "d3", "prompt": "An associate is choosing a model for extracting five fields from ~800 supplier invoices daily, with a clerk spot-checking 10%. What is the soundest selection process?", "options": ["Use the mid-tier model — it is a safe compromise for essentially any extraction task.", "Start with the most capable model and step down only when the budget owner complains about spend.", "Survey which models other companies use for invoice extraction and match their choice.", "State volume, latency, and accuracy requirements; pilot the cheapest model that could meet them."], "answer": 3, "why": "Requirements first, then the cheapest model that clears them, verified by measurement — stepping up selectively where evidence demands. Starting expensive anchors cost without evidence, compromise-by-default ignores this task's actual profile, and other companies' choices encode other companies' requirements.", "ref": "D3 Product and Model Selection — Lesson 3.3"}, {"id": "m27", "task": "3.4", "domain": "d3", "prompt": "A month-long support-planning chat has grown enormous. Claude now responds slowly, misses constraints set early in the conversation, and recently contradicted an agreed decision. What is happening and what fixes it?", "options": ["The model was updated mid-project, so its behavior changed; wait for the next release to settle.", "The chat exceeds its practical context window; summarize into a Project and restart.", "Nothing is wrong — contradictions are normal variance and can be corrected case by case.", "The prompts have grown too polite; firmer, more directive language restores compliance."], "answer": 1, "why": "Degradation, lost early constraints, and contradicted decisions in a very long chat are context-limit symptoms. The structural fix is summarize-and-restart with durable context persisted where every new chat inherits it. Blaming updates, tone, or 'variance' misdiagnoses a well-understood limitation.", "ref": "D3 Product and Model Selection — Lesson 3.4"}, {"id": "m28", "task": "3.4", "domain": "d3", "prompt": "Before closing a long analysis chat for the week, what habit best preserves the work for future sessions?", "options": ["Copy the whole transcript into the first message of next week's chat to restore context.", "Keep the chat open in a browser tab so that its context stays warm for next week's session.", "Nothing — the conversation history is a permanent record you can scroll back through.", "Ask for a structured summary of decisions and next steps, saved into Project knowledge."], "answer": 3, "why": "A chat is a workspace, not a filing cabinet: durable context survives through deliberate persistence of the distilled decisions, not through open tabs or raw transcript re-pasting (which re-creates the overload). The summary-and-persist habit is what makes restarts cheap.", "ref": "D3 Product and Model Selection — Lesson 3.4"}, {"id": "m29", "task": "4.1", "domain": "d4", "prompt": "A director asks an associate to 'get Claude to modernize our reporting.' Before any building, which use of Claude delivers the most value?", "options": ["Generate a modern report template right away, so the director sees quick, visible progress.", "Research reporting-tool vendors and their pricing so the options are on the table early.", "Analyze the request first: current reports, consumers, pain points, and success criteria.", "Rebuild last quarter's report in a new format as a demo of what modern could mean."], "answer": 2, "why": "'Modernize' is an unexamined requirement — building against it encodes guesses. Requirements analysis (who consumes what, what hurts, what success means) turns a vague mandate into confirmable acceptance criteria; templates, vendors, and demos come after the problem is defined.", "ref": "D4 Workflow Integration and Solution Design — Lesson 4.1"}, {"id": "m30", "task": "4.1", "domain": "d4", "prompt": "During requirements analysis, Claude infers that a new intake form 'must integrate with the CRM.' Nobody has actually said this. How should the associate handle Claude's inferred requirement?", "options": ["Discard it outright — a model should never propose requirements no stakeholder asked for.", "Treat it as a candidate requirement and validate it with stakeholders before committing.", "Ask Claude to rate its confidence and include the requirement if it exceeds 80%.", "Include it in the plan — the inference is reasonable and CRM integration is common."], "answer": 1, "why": "Claude's analytical value is surfacing candidate requirements humans might miss — but candidates become commitments only through stakeholder confirmation. Silently adopting inferences builds unrequested scope; discarding them wastes the surfacing value; model self-confidence is not stakeholder confirmation.", "ref": "D4 Workflow Integration and Solution Design — Lesson 4.1"}, {"id": "m31", "task": "4.2", "domain": "d4", "prompt": "An associate wants Claude's help optimizing the invoice-approval process. Which input to Claude produces the most actionable optimization analysis?", "options": ["\"List the top ten process-optimization frameworks and explain when each one applies.\"", "\"Our invoice process is slow. How do most companies usually speed this up?\"", "The org chart, so Claude understands who is involved at each stage of the approval.", "The documented process — steps, owners, durations, volumes — with a request to rank fixes."], "answer": 3, "why": "Optimization analysis is only as good as the process data provided: concrete steps, timings, and volumes let the model locate THIS process's bottlenecks and rank fixes by impact. Generic how-do-companies answers and framework lists produce advice unmoored from the actual workflow.", "ref": "D4 Workflow Integration and Solution Design — Lesson 4.2"}, {"id": "m32", "task": "4.2", "domain": "d4", "prompt": "Claude's plan for a system rollout schedules staff training in week 2, before the training environment exists in week 4 — a dependency error an experienced PM spots immediately. What does this illustrate about Claude-assisted planning?", "options": ["Draft plans save time, but dependency logic needs human validation before adoption.", "AI-generated plans are unusable for real project scheduling and shouldn't be attempted at all.", "The prompt should have instructed the model not to make any dependency errors.", "Planning needs the most capable model tier, which would not have made this mistake."], "answer": 0, "why": "Claude drafts plans fast and covers ground, but it reasons from what it is told — dependency and feasibility checking against reality is the human's contribution. Neither exhortations nor bigger models remove that review step; abandoning AI-assisted planning discards the acceleration.", "ref": "D4 Workflow Integration and Solution Design — Lesson 4.2"}, {"id": "m33", "task": "4.3", "domain": "d4", "prompt": "An associate designing a new client-intake workflow asks Claude for one recommended design and receives a sensible proposal. What is the main weakness of stopping here?", "options": ["No alternatives were compared against criteria, so its trade-offs stay invisible.", "Claude's designs must always be discarded and rebuilt from scratch by the humans.", "The proposal arrived too quickly to have been thought through and can't be trusted.", "A single proposal cannot be piloted, because there is no comparison to measure it."], "answer": 0, "why": "Design quality comes from comparing options against explicit criteria — a lone proposal hides its trade-offs (cost vs. flexibility, speed vs. control) because there is nothing to contrast them with. Speed isn't the defect, and single proposals pilot fine; they just shouldn't be chosen blind.", "ref": "D4 Workflow Integration and Solution Design — Lesson 4.3"}, {"id": "m34", "task": "4.3", "domain": "d4", "prompt": "After a two-week pilot of a Claude-assisted reporting design, feedback shows the drafts misjudge account health because a key data tab is missing from the inputs. What is the correct iteration response?", "options": ["Fix the diagnosed cause — require the missing tab, add a rubric — then re-pilot.", "Lower the success criteria so that the current design passes on the existing inputs.", "Declare the design a failure and return the team to the previous manual process now.", "Extend the pilot unchanged for another two weeks to gather more evidence before changing anything."], "answer": 0, "why": "Iteration means feeding pilot evidence back into the design: the failure traced to input completeness, so the revision targets that cause and re-tests against the unchanged yardstick. Prolonging a known-broken pilot, abandoning after one fixable finding, and moving the goalposts all waste what the pilot taught.", "ref": "D4 Workflow Integration and Solution Design — Lesson 4.3"}, {"id": "m35", "task": "4.4", "domain": "d4", "prompt": "A finance team is adding Claude to its month-end close. Which division of labor reflects sound workflow integration?", "options": ["Claude approves journal entries below a set threshold, to relieve the team's workload.", "Claude is excluded entirely — financial close processes cannot involve AI assistance.", "Claude drafts variance commentary and flags anomalies; accountants judge and sign off.", "Claude runs the entire close and accountants audit the results once each quarter."], "answer": 2, "why": "Integration assigns drudgery (drafting, summarizing, anomaly-flagging) to the AI and keeps judgment, approval, and accountability with qualified humans at the gates. Auto-approving entries IS a financial judgment; quarterly-audited automation removes the gate; blanket exclusion forfeits safe value.", "ref": "D4 Workflow Integration and Solution Design — Lesson 4.4"}, {"id": "m36", "task": "4.4", "domain": "d4", "prompt": "Two months after Claude was added to a proposal workflow, usage is near zero: writers say they don't know when to trust the drafts or who is responsible if an error ships. What did the integration skip?", "options": ["A mandate from leadership requiring writers to use the tool on every proposal they draft.", "A more capable model, which would have earned the writers' trust on its own.", "Nothing — adoption of a new tool always takes years to reach meaningful usage levels.", "Change management: trust boundaries, error ownership, and training on the new flow."], "answer": 3, "why": "A workflow redesign is complete only when the humans in it know their new roles: trust boundaries, override rights, and error ownership are design artifacts, not afterthoughts. Mandates force resentful usage of an unclear system, and no model tier answers 'who owns the mistake?'", "ref": "D4 Workflow Integration and Solution Design — Lesson 4.4"}, {"id": "m37", "task": "4.5", "domain": "d4", "prompt": "A department head asks an associate whether Claude could 'replace the two analysts who left.' Which response communicates value and limitations accurately?", "options": ["\"It absorbs the drafting and first-pass analysis; judgment and accountability don't transfer.\"", "\"No — AI tools are far too unreliable to be trusted with analytical work of this kind.\"", "\"Yes — current models outperform human analysts on most of the day-to-day analytical work.\"", "\"That depends entirely on which models ship over the next year, so it is too early to say.\""], "answer": 0, "why": "Honest stakeholder communication names what transfers (drafting, synthesis throughput) and what doesn't (judgment, verification, accountability), letting the leader plan on real capabilities. Hype creates a staffing hole discovered in production; doom forfeits the genuine capacity; deferral answers nothing.", "ref": "D4 Workflow Integration and Solution Design — Lesson 4.5"}, {"id": "m38", "task": "4.5", "domain": "d4", "prompt": "Preparing a stakeholder briefing on a new AI workflow, an associate lists limitations: hallucination risk, training-data recency, and context limits. What should accompany each limitation to make the briefing effective?", "options": ["The mitigation the workflow builds in: a verification step, current sources, restarts.", "A technical explanation of why transformer architectures exhibit each of these behaviors.", "A comparison showing that competitors' AI tools share exactly the same weaknesses.", "Nothing further — limitations should be stated plainly and not dwelt on in a briefing."], "answer": 0, "why": "Limitations land as operating rules when paired with the control that manages them — that's what turns risk disclosure into confidence. Architecture lectures answer unasked questions, whataboutism reassures no one, and bare lists read as unmanaged risk.", "ref": "D4 Workflow Integration and Solution Design — Lesson 4.5"}, {"id": "m39", "task": "5.1", "domain": "d5", "prompt": "When configuring a Claude Project, which placement of content is correct?", "options": ["Everything as knowledge documents, including the tone and escalation rules for chats.", "Everything in the first message of each chat, so the context is visible and auditable.", "Stable rules as instructions; documents as knowledge; one-off details in chat.", "Everything in the instructions, so that nothing is ever missed by any chat in the Project."], "answer": 2, "why": "Instructions define how every chat behaves (stable rules); knowledge supplies what chats consult (documents, swappable as they change); the chat itself holds only that conversation's specifics. Cramming everything into one layer either bloats standing orders with volatile facts or buries behavioral rules in documents.", "ref": "D5 Configuration and Knowledge Management — Lesson 5.1"}, {"id": "m40", "task": "5.1", "domain": "d5", "prompt": "A team lead 'set up' a shared Project but added no instructions or knowledge — it's just a folder of chats, and members still paste the style guide into each one. What is the corrective action?", "options": ["Create one pinned chat holding the style guide that everyone continues from each time.", "Configure it: durable rules as instructions, the style guide as a knowledge document.", "Ask members to paste the style guide more carefully, from the newest published version.", "Replace the Project with a longer prompt template kept in the team's internal wiki."], "answer": 1, "why": "The Project's value IS its configuration — instructions and knowledge inherited by every chat, current version, whole team. An unconfigured Project is a folder; pinned chats hit context limits and drift; wiki templates preserve the exact paste ritual the feature exists to remove.", "ref": "D5 Configuration and Knowledge Management — Lesson 5.1"}, {"id": "m41", "task": "5.2", "domain": "d5", "prompt": "Which knowledge source is the right candidate for a CONNECTOR rather than a file upload?", "options": ["Last year's annual report, used as a fixed baseline for historical comparisons.", "The company's brand-voice guide, revised roughly once a year by the marketing team.", "A published industry white paper that the team references occasionally during client work.", "The pipeline tracker in Google Drive, updated many times daily and queried for status."], "answer": 3, "why": "Connectors earn their governance overhead when the source changes faster than anyone would re-upload and currency matters — a live pipeline tracker is the textbook case. Slow-changing and static documents are well served by uploads with a review date.", "ref": "D5 Configuration and Knowledge Management — Lesson 5.2"}, {"id": "m42", "task": "5.2", "domain": "d5", "prompt": "To 'give Claude full context,' an associate proposes connecting the company's entire shared drive to a team Project. What is the primary problem?", "options": ["Connectors slow responses down in proportion to the size of the drive connected.", "Nothing — more available context reliably improves the quality of Claude's answers.", "Whole drives can only be connected by a workspace administrator, not by an associate.", "Scope is an access decision: a whole drive sweeps in HR, legal, and M&A material."], "answer": 3, "why": "Connecting a source grants the Project's users indirect reach into everything connected — data governance, not convenience, sets the boundary. Minimal scoping both protects sensitive folders and keeps retrieval signal high. 'More is always better' is exactly the instinct that causes connector incidents.", "ref": "D5 Configuration and Knowledge Management — Lesson 5.2"}, {"id": "m43", "task": "5.3", "domain": "d5", "prompt": "Which Project instruction is written in the most effective form?", "options": ["\"For pricing exceptions or contract terms, reply only 'Escalate to Deal Desk.'\"", "\"Always be accurate, and double-check your work before you give me an answer.\"", "\"Use good judgment about when a question falls outside your scope, and say so.\"", "\"Try to stay consistent with the way the team usually handles these requests.\""], "answer": 0, "why": "Effective instructions are specific and testable — named categories, exact required behavior, checkable compliance. Accuracy exhortations, appeals to unstated team norms, and delegated 'good judgment' all fail the could-a-stranger-verify-it test.", "ref": "D5 Configuration and Knowledge Management — Lesson 5.3"}, {"id": "m44", "task": "5.3", "domain": "d5", "prompt": "After every incident, a team adds another rule to its Project instructions. A year later there are 60+ rules, some contradictory, and behavior is erratic. What maintenance does this configuration need?", "options": ["Add further rules that cover the specific cases where the behavior has been erratic lately.", "Split the Project into two, each carrying about thirty of the existing rules.", "A pruning review: consolidate overlaps, resolve contradictions, keep few sharp rules.", "Move all sixty rules into a knowledge document and leave the instructions empty."], "answer": 2, "why": "Instruction sprawl is a failure mode: conflicting standing orders produce erratic compliance, and each incident-driven addition compounds it. The fix is editorial — prune, consolidate, prioritize. Adding more rules feeds the pathology; relocating the pile unread just changes where it rots.", "ref": "D5 Configuration and Knowledge Management — Lesson 5.3"}, {"id": "m45", "task": "5.4", "domain": "d5", "prompt": "Who or what should ensure a business team's Project knowledge stays current after policies and prices change?", "options": ["A named owner with update triggers and a periodic review sweep, with versioning.", "IT, through an annual archive-and-rebuild of every Project it maintains.", "The model, which should notice when the documents it was given have gone stale.", "Whichever team member is the next to notice that an answer has come back wrong."], "answer": 0, "why": "No model can detect that reality changed outside its knowledge — currency is an ownership process: someone accountable, event triggers tied to how the source documents actually change, and periodic sweeps. 'Whoever notices' means users absorb the errors first; annual rebuilds guarantee up to a year of staleness.", "ref": "D5 Configuration and Knowledge Management — Lesson 5.4"}, {"id": "m46", "task": "6.1", "domain": "d6", "prompt": "Which of the following is the MOST appropriate Claude use case for a business associate, as stated and without additional controls?", "options": ["Summarizing this week's customer feedback into themes for the product team.", "Sending AI-drafted responses to press inquiries without any human review.", "Issuing the final approval or denial decision on employee expense claims.", "Deciding which employees are selected for redundancy in a restructuring."], "answer": 0, "why": "Feedback summarization is low-stakes, reversible, easily spot-checked, and decision-supporting rather than decision-making. The other three are consequential decisions about people or public statements with no review before impact — categories where AI may assist analysis but a human must decide.", "ref": "D6 Governance, Risk, and Responsible Use — Lesson 6.1"}, {"id": "m47", "task": "6.1", "domain": "d6", "prompt": "A workflow began with Claude drafting rejection emails that recruiters personalized and sent. Over months, recruiters started forwarding the drafts unread, and now a manager proposes letting the system send them directly. What should an associate recognize?", "options": ["Scope creep from assist to decide: re-screen before automating any further.", "An efficiency win worth implementing, since candidate complaints have not increased.", "Natural maturation of the workflow — the automation has steadily earned trust over time.", "An opportunity to upgrade the model so the unread drafts come out even stronger."], "answer": 0, "why": "Use-case fitness was conditional on human judgment in the loop; when review decays to rubber-stamping and then removal, the workflow has silently crossed into autonomous decisions about people. The drift itself is the risk signal — re-screen before automating further, regardless of complaint volume so far.", "ref": "D6 Governance, Risk, and Responsible Use — Lesson 6.1"}, {"id": "m48", "task": "6.2", "domain": "d6", "prompt": "An HR associate wants Claude's help analyzing exit-interview themes. The transcripts contain names, managers' names, and health disclosures. Policy restricts sharing personal data with AI tools. What is the compliant approach?", "options": ["Upload the transcripts unmodified, since exit interviews are internal documents.", "Upload everything, but add 'treat this as confidential' to the top of the prompt.", "Redact names and the health disclosures, then analyze the anonymized themes.", "Cancel the analysis — exit interview data is too sensitive for any AI use at all."], "answer": 2, "why": "Theme analysis survives anonymization intact, and health disclosures carry heightened protection in most regimes — redaction before upload satisfies policy while preserving the value. 'Internal' is not a data classification, prompt-level confidentiality requests are not controls, and abandonment is unnecessary when minimization works.", "ref": "D6 Governance, Risk, and Responsible Use — Lesson 6.2"}, {"id": "m49", "task": "6.2", "domain": "d6", "prompt": "An associate removed the name column from a dataset before uploading it, but each row still contains job title, office location, and start date in a 40-person company. What should they consider?", "options": ["Quasi-identifiers can re-identify people in a 40-person firm; generalize the fields.", "Adding a 'do not identify individuals' instruction resolves the residual risk here.", "Anonymization requirements apply only to customer data, not internal employee records.", "The dataset is anonymized — the name column was removed before it was uploaded."], "answer": 0, "why": "'Marketing Director, Munich office, started March 2024' identifies one person as surely as their name in a 40-person firm — anonymization is defeating re-identification, not deleting one column. Employee data is personal data, and model instructions are not privacy controls.", "ref": "D6 Governance, Risk, and Responsible Use — Lesson 6.2"}, {"id": "m50", "task": "6.2", "domain": "d6", "prompt": "A teammate suggests pasting a customer's contract into a personal free-tier AI account 'since our corporate Claude workspace is at its seat limit this week.' What is the correct response?", "options": ["Agree, provided the contract is deleted from the personal account immediately afterwards.", "Decline: customer data in an unapproved personal tool breaches policy.", "Agree, but paste only the first half of the contract, to reduce the total exposure.", "Agree if the customer's name and signature block are replaced with a neutral alias."], "answer": 1, "why": "The violation is the destination, not the volume: unapproved personal tools sit outside the org's data-processing agreements and controls, and customer confidentiality clauses typically prohibit exactly this. Post-hoc deletion, partial pastes, and cosmetic aliases don't change the destination.", "ref": "D6 Governance, Risk, and Responsible Use — Lesson 6.2"}, {"id": "m51", "task": "6.3", "domain": "d6", "prompt": "An associate's new AI use case — summarizing recorded customer calls — is not mentioned anywhere in the company's AI policy. How should they proceed?", "options": ["Treat undefined as not yet approved and ask the governance owner about consent.", "Wait for the next annual policy revision to address the case before doing anything.", "Proceed — anything the policy does not explicitly prohibit is permitted by default.", "Proceed quietly for now, and stop the moment somebody raises an objection to it."], "answer": 0, "why": "Policy silence on a novel, data-sensitive use case is a question, not a permission — recorded calls involve consent and personal data, exactly what governance exists to evaluate. Silence-as-permission and forgiveness-later create shadow AI; waiting a year is unnecessary when a governance channel exists.", "ref": "D6 Governance, Risk, and Responsible Use — Lesson 6.3"}, {"id": "m52", "task": "6.3", "domain": "d6", "prompt": "Company policy requires labeling AI-assisted content in client deliverables. A manager tells an associate to skip the label 'because clients get nervous about AI.' What should the associate do?", "options": ["Skip the label, but keep private notes proving that AI assistance was used.", "Add the label in a font small enough that clients are unlikely to notice it.", "Follow the manager's instruction — managers outrank written policy within their own area.", "Keep the disclosure, cite the policy, and escalate to the policy owner if pressed."], "answer": 3, "why": "A manager's preference doesn't amend policy — and disclosure rules exist precisely because omitting them misleads clients. Comply with the policy, surface the conflict through the channel that owns it. Secret notes and micro-fonts are bad-faith versions of the same violation.", "ref": "D6 Governance, Risk, and Responsible Use — Lesson 6.3"}, {"id": "m53", "task": "6.4", "domain": "d6", "prompt": "A published, Claude-assisted market report is found to contain a material factual error. The associate who produced it says 'the AI generated that section.' What is the correct accountability position?", "options": ["Correct — responsibility sits with the tool that generated the erroneous section.", "The human who reviewed, approved, and published it owns the error; review is why.", "Nobody is accountable, since the governance team approved this workflow already.", "Responsibility is split evenly between the associate and the model's vendor."], "answer": 1, "why": "'The AI did it' is the accountability anti-pattern: tools don't hold responsibility, publishers do. A human name stands behind every consequential output — that principle is what makes review non-optional, and approved workflows assign accountability rather than dissolving it.", "ref": "D6 Governance, Risk, and Responsible Use — Lesson 6.4"}, {"id": "m54", "task": "6.4", "domain": "d6", "prompt": "Before relying on a Claude-assisted scoring aid that prioritizes which customer complaints get expedited handling, what bias check is most important?", "options": ["Compare expedite rates across customer groups over a sample period, looking for skew.", "Confirm the scoring prompt contains no demographic words or protected attributes.", "None — complaint routing is an operational process, not a people-affecting one.", "Ask the model whether its own scoring is fair to all customer groups equally."], "answer": 0, "why": "Bias is detected in outcomes, not vocabulary: proxies (product tier, region, writing style) can skew results without a single demographic term in the prompt. Prioritization decides whose problems get solved first — that is people-affecting, and models cannot audit their own fairness.", "ref": "D6 Governance, Risk, and Responsible Use — Lesson 6.4"}, {"id": "m55", "task": "7.1", "domain": "d7", "prompt": "Claude's answers about a team's travel policy are correct on general rules but consistently wrong about reimbursement limits, which changed last month. What is the most likely cause and fix?", "options": ["Context overflow in a long conversation — start a fresh chat and ask again.", "The prompt lacks emphasis — add 'pay special attention to reimbursement limits.'", "The model tier is too low — upgrade to a stronger model and ask the same question.", "The Project's policy document predates the change — replace it and re-test."], "answer": 3, "why": "Correct-in-general but wrong-on-recent-specifics is the signature of a stale knowledge source: the model faithfully reports the outdated document it was given. Model tier, emphasis phrases, and fresh chats all leave the wrong document in place.", "ref": "D7 Troubleshooting and Optimization — Lesson 7.1"}, {"id": "m56", "task": "7.1", "domain": "d7", "prompt": "A troubleshooting associate changes the prompt wording, swaps the model, AND replaces a knowledge file — and the workflow starts working. What is the problem with this outcome?", "options": ["Nothing is wrong — the workflow works again, which is the point of troubleshooting.", "The model swap was wasteful; the other two changes cost nothing and can stay.", "Each of the three fixes should have been applied twice, to confirm it really held.", "Three variables changed at once, so the actual cause — and the diagnosis — is lost."], "answer": 3, "why": "Change-one-variable-and-re-test is what converts a fix into knowledge: bundled changes hide the cause, may leave you paying for an unneeded model upgrade, and teach nothing reusable. 'It works now' without knowing why is a debt, not a resolution.", "ref": "D7 Troubleshooting and Optimization — Lesson 7.1"}, {"id": "m57", "task": "7.2", "domain": "d7", "prompt": "A month after launch, an AI-drafting workflow's outputs are consistently edited to shorten the openings and remove a boilerplate paragraph — the same edits, by many users. What should the workflow owner do?", "options": ["Ask users to stop editing the drafts so the outputs stay measurable over time.", "Nothing — editing the drafts is exactly what the users are supposed to be doing.", "Treat the repeated edits as calibration feedback and update the instructions.", "Rebuild the workflow on a more capable model that writes tighter openings."], "answer": 2, "why": "Systematic identical edits are the workflow telling you its default output is mis-calibrated — encoding the pattern into the configuration removes repeated manual labor. Ignoring the signal wastes everyone's time forever; suppressing edits destroys the feedback; the model isn't the variable that's wrong.", "ref": "D7 Troubleshooting and Optimization — Lesson 7.2"}, {"id": "m58", "task": "7.2", "domain": "d7", "prompt": "An executive sponsor emails: 'My assistant said the AI summaries missed the point once last week. Shut the pilot down?' Weekly metrics show a 94% acceptance rate across 300 summaries. How should the associate respond?", "options": ["Investigate the failed summary, report it alongside the 94% data, and continue.", "Remove the assistant's account from the pilot group so the complaints stop coming.", "Dismiss the complaint — one failure in 300 summaries is statistically negligible.", "Shut the pilot down — a sponsor's concern outweighs the acceptance metrics."], "answer": 0, "why": "Anecdotes get investigated, not obeyed and not dismissed: the single case may reveal a real edge case worth fixing, while the systematic evidence (94%/300) is what decisions should rest on. Killing a measured pilot over unexamined n=1 — or shooting the messenger — both abandon evidence-based adjustment.", "ref": "D7 Troubleshooting and Optimization — Lesson 7.2"}, {"id": "m59", "task": "7.3", "domain": "d7", "prompt": "A working AI-assisted report pipeline costs 40 staff-minutes per report: 10 for drafting with re-pasted context, 25 waiting in a single reviewer's queue, and 5 for distribution. Where should optimization start?", "options": ["Distribution, since it is the final step and the one that users actually see.", "All three steps at once, since that produces the largest total improvement.", "The drafting step — response speed is the core of any AI-assisted workflow.", "The review queue — it is 60% of cycle time; restructure it and add a Project."], "answer": 3, "why": "Optimization follows the profile: the bottleneck is the human queue, not the AI seconds — restructuring review attention (and templating the context ritual) attacks the actual 25 minutes. Polishing the smallest slices or changing everything at once ignores where the time goes and blurs cause and effect.", "ref": "D7 Troubleshooting and Optimization — Lesson 7.3"}, {"id": "m60", "task": "7.3", "domain": "d7", "prompt": "To cut costs, a team moves its customer-visible FAQ generation to the fastest, cheapest model and removes the editorial review 'since quality has been fine for months.' What optimization principle does this violate?", "options": ["Editorial review should have been replaced by a second model, not removed outright.", "None — removing steps that no longer earn their keep is exactly what optimizing is.", "Customer-facing content should always run on the most capable model available.", "Efficiency changes must keep the quality safeguard and a visible quality metric."], "answer": 3, "why": "The review net is what MADE the historical quality 'fine' — removing it while simultaneously reducing model capability changes two variables against quality with zero instrumentation on customer-visible output. Right-sizing models is legitimate; doing it blind and netless is the classic effectiveness-for-efficiency trade the exam penalizes.", "ref": "D7 Troubleshooting and Optimization — Lesson 7.3"}];

  window.CCAF = { domains, themes, tasks, scenarios, questions, cheat, mock,
    taskById: Object.fromEntries(tasks.map((t) => [t.id, t])),
    questionById: Object.fromEntries(questions.map((q) => [q.id, q])),
    domainById: Object.fromEntries(domains.map((d) => [d.id, d])),
  };
})();
